WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[13368] = { title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him while there's still time!", objectives = "" }
WordHunterWoW_QuestEN[13372] = { title = "The Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[13374] = { title = "Amped for Revolt!", description = "{name}, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!\n\nRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[13375] = { title = "The Heroic Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[13381] = { title = "Watts My Target", description = "Put on your lucky socks, {name}, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!\n\nRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, {name}!  I'll see you when it's over.", objectives = "" }
WordHunterWoW_QuestEN[13384] = { title = "Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", objectives = "" }
WordHunterWoW_QuestEN[13385] = { title = "Heroic Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", objectives = "" }
WordHunterWoW_QuestEN[13386] = { title = "Exploiting an Opening", description = "I've got an interesting assignment for you, {name}.  If you're up for a challenge, that is.\n\nWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.\n\nWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.\n\nWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[13387] = { title = "Securing the Perimeter", description = "The saronite bombs are in place, {name}.  We're only going to get one shot at this, however.  Let's make it count.\n\nWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.", objectives = "" }
WordHunterWoW_QuestEN[13388] = { title = "Set it Off!", description = "Things are looking good.  Let's do this.\n\nThe stack of bombs is right near the pit.  I'll start to evacuate the men.", objectives = "" }
WordHunterWoW_QuestEN[13389] = { title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", objectives = "" }
WordHunterWoW_QuestEN[13390] = { title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", objectives = "" }
WordHunterWoW_QuestEN[13391] = { title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", objectives = "" }
WordHunterWoW_QuestEN[13392] = { title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", objectives = "" }
WordHunterWoW_QuestEN[13393] = { title = "Field Repairs", description = "All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.\n\nWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.\n\nIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.\n\nSure, you'll be a little outnumbered, but I've a lot of faith in you!", objectives = "" }
WordHunterWoW_QuestEN[13394] = { title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", objectives = "" }
WordHunterWoW_QuestEN[13395] = { title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", objectives = "" }
WordHunterWoW_QuestEN[13396] = { title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", objectives = "" }
WordHunterWoW_QuestEN[13397] = { title = "Sindragosa's Fall", description = "You're a real star, {name}.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.\n\nBut with you, it's always a guaranteed thing.  Like gnomish clockwork!\n\nAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.\n\nI hate cultists.", objectives = "" }
WordHunterWoW_QuestEN[13398] = { title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", objectives = "" }
WordHunterWoW_QuestEN[13399] = { title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[13400] = { title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", objectives = "" }
WordHunterWoW_QuestEN[13401] = { title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", objectives = "" }
WordHunterWoW_QuestEN[13402] = { title = "Tirion's Help", description = "It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.\n\nWe must act on this information immediately.  Unfortunately, we must do so in secret.\n\nArthas's agents are everywhere and if he finds out, our plan is dead in the water.\n\nWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.", objectives = "" }
WordHunterWoW_QuestEN[13403] = { title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", objectives = "" }
WordHunterWoW_QuestEN[13408] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "" }
WordHunterWoW_QuestEN[13409] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[13410] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "" }
WordHunterWoW_QuestEN[13411] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[13412] = { title = "Corastrasza", description = "Greetings, {class}. Might I impose on you for a favor?\n\nCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.\n\nThough he will never say it, he worries about her, and would welcome any news of her well-being.\n\nPlease seek her out. Ask her to put her pride aside and send word to her brother.", objectives = "" }
WordHunterWoW_QuestEN[13413] = { title = "Aces High!", description = "You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....\n\nI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.\n\nTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.\n\nThe opportunity is yours for the asking...", objectives = "" }
WordHunterWoW_QuestEN[13414] = { title = "Aces High!", description = "Again we meet, {race}. I confess, your presence is beginning to grow on me.\n\nAm I correct in assuming that you've come to hone your aerial combat skills?\n\nAs always, my pets stand ready to bring fiery destruction to the enemy.\n\nSpeak, and they shall be at your disposal.", objectives = "" }
WordHunterWoW_QuestEN[13415] = { title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ", objectives = "" }
WordHunterWoW_QuestEN[13416] = { title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ", objectives = "" }
WordHunterWoW_QuestEN[13418] = { title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart.", objectives = "" }
WordHunterWoW_QuestEN[13419] = { title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart and lend a hand.", objectives = "" }
WordHunterWoW_QuestEN[13420] = { title = "Everfrost", description = "This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.\n\nKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.", objectives = "" }
WordHunterWoW_QuestEN[13422] = { title = "Maintaining Discipline", description = "You've succeeded where others have failed.  Yet you cannot rest on your laurels.\n\nYou must show others what strength and commitment really mean.\n\nThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.", objectives = "" }
WordHunterWoW_QuestEN[13423] = { title = "Defending Your Title", description = "Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.\n\nShow these upstarts what you're made of.", objectives = "" }
WordHunterWoW_QuestEN[13424] = { title = "Back to the Pit", description = "To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.\n\nHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.", objectives = "" }
WordHunterWoW_QuestEN[13425] = { title = "The Aberrations Must Die", description = "It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.\n\nThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.\n\nSeize the frost oil they wield and use it to freeze their abominable plagued eggs.", objectives = "" }
WordHunterWoW_QuestEN[13426] = { title = "Xarantaur, the Witness", description = "It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.\n\nMeet up with him, {name}. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.", objectives = "" }
WordHunterWoW_QuestEN[13429] = { title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", objectives = "" }
WordHunterWoW_QuestEN[13430] = { title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", objectives = "" }
WordHunterWoW_QuestEN[13431] = { title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!\n", objectives = "" }
WordHunterWoW_QuestEN[13432] = { title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", objectives = "" }
