WordHunterWoW_QuestEN[13479] = { title = "The Great Egg Hunt", description = "Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. \n\nI'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.", objectives = "" }
WordHunterWoW_QuestEN[13480] = { title = "The Great Egg Hunt", description = "Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you.\n\nI'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.", objectives = "" }
WordHunterWoW_QuestEN[13481] = { title = "Let's Get Out of Here!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "" }
WordHunterWoW_QuestEN[13482] = { title = "Let's Get Out of Here", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "" }
WordHunterWoW_QuestEN[13483] = { title = "Spring Gatherers", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities--Razor Hill, Brill, Bloodhoof Village, and Falconwing Square--who have been recruiting egg hunters for help with some research they're doing. I don't know the particulars, but I'm sure they'd tell you.", objectives = "" }
WordHunterWoW_QuestEN[13484] = { title = "Spring Collectors", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities --Goldshire, Kharanos, Dolanaar, and Azure Watch--who have been recruiting egg hunters for help with some research they're doing. I don't know the particulars, but I'm sure they'd tell you.", objectives = "" }
