WordHunterWoW_QuestEN[13501] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[13502] = { title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this egg basket and go hunting for brightly colored eggs. Return to me with the basket when you've found ten Noblegarden chocolates, please.", objectives = "" }
WordHunterWoW_QuestEN[13503] = { title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here--take this egg basket and go hunting for brightly colored eggs. Return to me with the basket when you've found ten Noblegarden chocolates.", objectives = "" }
WordHunterWoW_QuestEN[13504] = { title = "Shatterspear Laborers", description = "There are a large number of Shatterspear trolls picking through the ruins to the north and northeast. I suspect that they're looking for magical artifacts, but none of our scouts have reported the discovery of anything of significance turning up from their digs. They may well just be fueling their war.\n\nOne thing is fairly certain though: less laborers would slow down their offensive, so less laborers is what they're going to get. You in?", objectives = "" }
WordHunterWoW_QuestEN[13505] = { title = "Remnants of the Highborne", description = "There are several ruins similar to these spread through Darkshore, many of them inhabited by the troubled spirits of the Highborne. Out of mild courtesy for their cursed souls, we haven't been overly proactive about stripping the ruins of artifacts, but those hesitancies vanish in light of this new troll threat.\n\nWhile you're aiding the Sentinels in their goals within the ruins, please collect any artifacts that you stumble upon and bring them back to me. I would like to preserve what little I can.", objectives = "" }
WordHunterWoW_QuestEN[13506] = { title = "Reason to Worry", description = "These appear to be orders dispatched to the overseers at the ruins from a superior in the Shatterspear War Camp. Most of the document contains negligible strategic value, but a couple lines stick out to you.\n\n\"We captured another night elf spying on our operation. She has been taken back to the camp to be tortured for more information. Keep an eye out for additional spies - we cannot afford for our operation to be compromised.\"\n\nThe Lieutenant will surely want this information.", objectives = "" }
WordHunterWoW_QuestEN[13507] = { title = "Denying Manpower", description = "To the north, the Shatterspear have a war camp where they are constructing their catapults. The camp is guarded by some of their mystics, but I've started receiving reports that there are sightings of orcs and tauren there as well.\n\nI don't want to make any assumptions as to what that suggests, but I do want you to go in and kill them before they can make any further strikes on our Sentinels.", objectives = "" }
WordHunterWoW_QuestEN[13508] = { title = "Swift Response", description = "I have a scout that we lost contact with a couple days ago. I assumed her dead, but it appears that she's been captured. The trolls indicate that they have at least two captives though... the only other person that comes to mind is Alanndarian Nightsong, a civilian that was in the area against my advisement early yesterday.\n\nThe Shatterspear have established a war camp to the north - it is almost certainly where any of their prisoners are being taken. Find them and free them if you're able.", objectives = "" }
WordHunterWoW_QuestEN[13509] = { title = "War Supplies", description = "The trolls are building their forces and supplies at the war camp to the north. When they feel they are ready, they will almost certainly launch their attack on Lor'danel from that location. It shouldn't take us long to rout this rabble, but I'm not one for taking unnecessary risks.\n\nI want you to fight your way into the war camp and set fire to any stockpiles of supplies that you see. The setback should buy us quite a bit of time before they can muster a counterattack.", objectives = "" }
WordHunterWoW_QuestEN[13510] = { title = "Timely Arrival", description = "It's good to see you. I wasn't looking forward to enduring what Alanndarian did, so the rescue is somewhat welcome.\n\nI saw the troll leader before I was captured, and thought I had the perfect opportunity to kill him, but he's protected by some sort of magic shield. Morra needs to know before she mounts her assault, but first, we need to get out of here.\n\nHelp me to the dock - I'll make my way to Lor'danel via water, and you can go back to Morra with the intel.", objectives = "" }
WordHunterWoW_QuestEN[13511] = { title = "One Bitter Wish", description = "Morra sent you? I should have listened to her - it's just hard to take trolls seriously I guess.\n\n<Alanndarian lets out a weak chuckle.>\n\nIt's way too late for that anyway. We're mortal now... this is the fate we have to face, one way or another. I've had time to accept that.\n\nI have one request though... kill the torturer that did this to me. They call him Rit'ko... you can find him just ahead with the other prisoner.\n\n<Alanndarian offers a small smile, then winces and slumps back over in pain.>", objectives = "" }
WordHunterWoW_QuestEN[13512] = { title = "Strategic Strikes", description = "Striking at the head of the beast doesn't work if there's another head to replace it. Before we can kill their leader, we need to kill the subleaders that may try to step up. Right now, they are not as well defended, and you should be able to best them without much support.\n\nTake this dryad spear and hunt them down. The poison on its tip should slow their incantations. My scouts reported one inside the water chamber in the ruins to the east and the other past the remains of the tower to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[13513] = { title = "On the Brink", description = "I've already been working on something for breaking down their protective wards. With a focus based in their power and a bit of druidic magic, we should be able to breach their shields.\n\nFind their shaman to the east and southeast and recover several of their amulets. I will prepare them and imbue an arrow that you can deliver to Sandrya Moonfall for the attack.", objectives = "" }
WordHunterWoW_QuestEN[13514] = { title = "The Ancients' Ire", description = "Come to join the offensive? If you're looking for Sandrya Moonfall, she's leading the attack on the Shatterspear leader at the cave in the back of the vale, you can meet her there.\n\nWhile you're here though, we could certainly use your help with routing the rest of their tribe. Go ahead and take the company of one of the Vengeful Protectors there and see to it that every last building is destroyed and every last troll killed. We can't have them coming back for revenge when we're less prepared, can we?", objectives = "" }
WordHunterWoW_QuestEN[13515] = { title = "Ending the Threat", description = "Their leader and his guard are before us. My Sentinels are ready to take care of his guard, we only awaited this arrow to seal their leader's fate.\n\nLet me know when you are prepared to attack. As soon as my Sentinels engage, I will shatter the leader's shield, and we will assault him together. Strike swiftly and we can rout this threat to our lands here and now.\n\nWe await only you - speak to me when ready.", objectives = "" }
WordHunterWoW_QuestEN[13518] = { title = "The Last Wave of Survivors", description = "It's too late for Laird, he didn't make it in time.\n\nThe last wave of night elves from Auberdine attempted to escape a couple of hours ago. They stayed in their old home, clinging to the hope that it could be salvaged, but it seems they were finally forced out. I fear many of them won't make it, like Laird did not.\n\nQuickly, go down the coast to the west and find any survivors that you can. We're sending Sentinels and Hippogryphs down, but every moment counts - we need to know which ones might make it.", objectives = "" }
WordHunterWoW_QuestEN[13519] = { title = "The Twilight's Hammer", description = "A group of Twilight's Hammer cultists has set up camp southwest of here.  They're preparing an army of water elementals to use against Lor'danel.\n\nTheir leader, High Cultist Azerynn, has pacts with the dark Old Gods that grant his sect power over the elements.  Go and deal with them before it's too late, {name}.\n\nThe cataclysm has left the elemental spirits in disarray... it's only a matter of time until they have enough elementals to overcome our defenses.", objectives = "" }
WordHunterWoW_QuestEN[13520] = { title = "The Boon of the Seas", description = "It is good to see you. You were key in ensuring that our loved ones made it home, and I hold some hope that you may yet help us further.\n\nLike Laird, their wounds will be grave - every one of them battered by the coast and assaulted by the elementals. I am doing what I can, but it seems that those elementals hosted a toxin that is weakening their ability to heal. I believe I can concoct a salve, but I will need secretion from the muscles of the clams that inhabit this coast. Can you help me?", objectives = "" }
WordHunterWoW_QuestEN[13521] = { title = "Buzzbox 413", description = "Greetings!\n\nI'm helping Tharnariun here try to unravel what's been corrupting the wildlife in the area. I've set up some machines in the field that can analyze animal parts and possible corruption agents. If you can get me some good samples, we can get to the bottom of this affliction quickly.\n\nThe first machine is Buzzbox 413. I set it up on the beach just east of town. I'll need you to gather some flesh from the nearby corrupted tide crawlers and bring it to the machine so that I can analyze it.", objectives = "" }
WordHunterWoW_QuestEN[13522] = { title = "Threat from the Water", description = "Some of the survivors of this last Auberdine attack are still trying to make it up the coast to safety. We only caught word that they were coming within the last hour. I wish that we had more warning...\n\nThe coastline west of us is swarming with vile spray, vicious little water elementals. We need to clear them out if any of the survivors are to have a chance of making it to Lor'danel. Depart immediately and kill every elemental you see.", objectives = "" }
WordHunterWoW_QuestEN[13523] = { title = "Power Over the Tides", description = "Do not worry about me.  My wounds are deep and death will soon come to me.\n\nIt is all up to you now... you must stop the Twilight's Hammer.\n\nThe Old Gods they worship have granted them power over the restless water spirits... but that power is tenuous.  Channel Elune's presence through this orb once the elementals have been defeated.\n\nUse the power of Elune to banish the spirits permanently.", objectives = "" }
WordHunterWoW_QuestEN[13525] = { title = "What's Happening to the Blackwood Furbolg?", description = "Our ancestors lived alongside the Blackwood furbolgs for generations. But recently, we have lost contact with their settlements deeper in the forest. One of their larger villages, Blackwood Hold, can be found to the south.\n\nTravel there and find Elder Brolg. Ask him why his people have withdrawn from us and offer your help, if necessary.", objectives = "" }
WordHunterWoW_QuestEN[13526] = { title = "The Bear's Paw", description = "The foul satyr of Felwood have started to introduce their poison into Darkshore, into our lands. Their corruption kills the land and twists the creatures who live in it. My people are no exception.\n\nOur magic alone is not enough to bring them back to their senses. There is an herb, called bear's paw, that we use to break fevers and fortify the weak. With its help, we may be able to break the influence of the satyr. The herb grows in the wilds around the village.", objectives = "" }
WordHunterWoW_QuestEN[13527] = { title = "No Accounting for Taste", description = "<The machine buzzes for a few moments  before Wizbang's voice breaks through.>\n\nInteresting! The source of this corruption definitely came from something external--no surprises there--but it appears that in this case they've been eating something foul. A large mammal probably. Most likely a bear.\n\nSearch the beach for a bear carcass for me. Slightly east of there would make the most sense, on the inland side of the beach. Bring me the sample back at town.", objectives = "" }
WordHunterWoW_QuestEN[13528] = { title = "Buzzbox 723", description = "There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now.\n\nBuzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.", objectives = "" }
WordHunterWoW_QuestEN[13529] = { title = "The Corruption's Source", description = "I rushed here as soon as I heard the news from Wizbang. I know who's behind this mess now. Zenn Foulhoof.\n\nHe came over from Teldrassil after he was chased out for performing perverse magics. The kinds of corruption he employs are not welcome among my people, and it seems he's taken it a step further this time, perhaps as some form of revenge.\n\nZenn's been given too many chances, it's time we remove this threat to all that is natural. Kill Zenn and his minions, and then find me back in Lor'danel.", objectives = "" }
WordHunterWoW_QuestEN[13537] = { title = "A Taste for Grouper", description = "Between boat rides and building, I'm exhausted... and hungry. You know what sounds tasty? Fish. Fish sound delicious.\n\nDarkshore is known for its grouper. If you fish me up some, I'll make it worth your time.", objectives = "" }
WordHunterWoW_QuestEN[13538] = { title = "Southern Sabotage", description = "The three towers south of the Wintergrasp river are draining power from the Fortress! \n\nDestroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!", objectives = "" }
WordHunterWoW_QuestEN[13539] = { title = "Toppling the Towers", description = "While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.\n\n\"Attack him where he is unprepared, appear where you are not expected.\"\n\n{name}, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.\n\nReturn to me once you've destroyed a tower.", objectives = "" }
WordHunterWoW_QuestEN[13542] = { title = "Against the Wind", description = "If we're going to take the Ruins of Auberdine back from the Twilight's Hammer, the elementals that they've summoned must be dealt with on a permanent basis.\n\nThat's where you come in.\n\nLook, I don't expect you to retake the town, but while we're healing up here, you can soften them up for us.\n\nTo permanently deal with the frenzied cyclones, head west, kill them, take their bracers, and put them in the moonwell. That will destroy the bracers and keep those elementals from being resummoned.", objectives = "" }
WordHunterWoW_QuestEN[13543] = { title = "Three Hammers to Break", description = "I've flown through the ruins of Auberdine on a scouting mission. There are three Twilight's Hammer cultists that are responsible for the elementals that have overrun the destroyed town.\n\nHead west into the ruins. Seek out and slay Cloudtamer Wildmane, Windmaster Tzu-Tzu, and Skylord Braax.\n\nOnly then will Sentinel Selarin and her forces stand a chance of taking back their home.", objectives = "" }
WordHunterWoW_QuestEN[13544] = { title = "The Bear's Blessing", description = "Before the bear's paw can be used to cleanse the afflicted, it must be completed and blessed. To the north of the village roams a tallstrider named Fleetfoot. You'll need its tailfeathers to complete the herb bundle.\n\nBring the tailfeathers and the bear's paw bundle to the ancient bear statue in the ruins around the Grove of the Ancient, further north of where you'll find Fleetfoot.\n\nWhile at the shrine, combine the tailfeathers with the bear's paw and receive the bear spirit's blessing.", objectives = "" }
WordHunterWoW_QuestEN[13545] = { title = "Cleansing the Afflicted", description = "With the sacred herbs and the bear's blessing, you must use this herb bundle to cleanse my brothers. The corruption spilling over from Felwood has driven them mad and they will attack any who come near. Expect the afflicted Blackwood to be angry with you until you have slain the spirits of corruption that haunt them.\n\nWhen you have freed my brothers from their madness, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13546] = { title = "The Defiler", description = "The Jadefire satyrs of Felwood have found their way into Darkshore, tainting the land, water, and creatures they encounter. You've seen what their corruption has done to my people and their homes. If we do not turn back the satyrs, all of us will share that fate.\n\nWithin the cave to the east is Sharax the Defiler, the satyr responsible for the ills of the Blackwood. Slay him, {name}, and free us from his influence. Show the satyr that the Blackwood will not lay down and die so easily.", objectives = "" }
WordHunterWoW_QuestEN[13547] = { title = "Coaxing the Spirits", description = "Your friends back at the refugee camp are unaware of the true and imminent danger that the Twilight's Hammer cultists have already brought into the world.\n\nFor you to deal with that, we'll first need to get some help from the dead of Auberdine.\n\nSearch through the ruins of the town and find the corpses of Thundris Windweaver, Elissa Starbreeze, Taldan, and Caylais Moonfeather. Coax the spirits from their bodies and then return with them to me here.", objectives = "" }
WordHunterWoW_QuestEN[13548] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[13549] = { title = "Tails Up", description = "Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females!\n\nToo bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him?\n\nPut the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.", objectives = "" }
WordHunterWoW_QuestEN[13554] = { title = "A Cure In The Dark", description = "<Some unintelligible speech spews forth from the machine before you make out Wizbang's voice again.>\n\nDuskrats! They've been eating the duskrats! Those little buggers only come from one place, a cave against the cliff-face to the east. Find a path up to the northeast and look for an opening under the waterfall.\n\nThe duskrats there are either getting into something nasty or someone's intentionally spreading some agent through them - in either case, just bring me back several samples of the stuff!", objectives = "" }
WordHunterWoW_QuestEN[13556] = { title = "Eggs for Dubra'Jin", description = "How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin.\n\nHow ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid!\n\nWe need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.", objectives = "" }
WordHunterWoW_QuestEN[13557] = { title = "Bearer of Good Fortune", description = "This key appears to be for the animal cages spread throughout Cliffspring Hollow. Tharnariun would surely appreciate if you took advantage of the situation to free some of the uncorrupted duskrats and thistle bears that are still being held captive.", objectives = "" }
WordHunterWoW_QuestEN[13558] = { title = "Call Down the Thunder", description = "Aetherion is almost in our world, but he can still be dealt with!\n\nAt the end of the dock floats a ritual orb. I want you to use it to complete the ritual, beckoning the elemental lord down from his vortex.\n\nTrust me, {name}, I and the other spirits that you have freed will greatly weaken Aetherion. However, it will be up to you to finish him off for good and save the Kaldorei people of Darkshore from utter destruction.\n\nDeliver his essence to Corvine Moonrise at the refugee camp so he will know.", objectives = "" }
WordHunterWoW_QuestEN[13560] = { title = "An Ocean Not So Deep", description = "You look like an able sort!\n\nThere are a great number of wrecks off of the coast here... most old, some new. For quite some time, I've been trying to get at their holds and put their valuables to more use, but there's a nasty infestation of murlocs that seem to have other ideas. I've sent scores of adventurers and none have returned.\n\nWorry not, I've learned my lesson, and that is not your fate. Swim to the due north and look for Gary. He'll explain the new plan. It's pretty simple really.", objectives = "" }
WordHunterWoW_QuestEN[13561] = { title = "Solace for the Highborne", description = "I have come to Bashal'Aran to grant peace to the troubled spirits of the Highborne, but I find my hand hesitates with each blow. If you would like to aid me, you would have my gratitude.", objectives = "" }
WordHunterWoW_QuestEN[13562] = { title = "The Final Flame of Bashal'Aran", description = "It is in times like these that we are forced to stop and examine our way of life. We are mortal now, and no matter how much we desire otherwise, we are deserving of our new place in this world.\n\nBashal'Aran, down the road to the south, once a city of our ancestors, it now is home to their cursed ghosts. We held hope of salvation for them as with ourselves, but we have left them in torment for too long. It is time to extinguish the Final Flame of Bashal'Aran.", objectives = "" }
WordHunterWoW_QuestEN[13563] = { title = "A Love Eternal", description = "I would like to extend my gratitude for saving us. I would call myself fortunate, but my beloved, Anaya, lays long dead. I am alone and deeply troubled, and sadly, I require your aid yet again.\n\nWandering the woods of Darkshore after my rescue, I found myself in the ruins of Bashal'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.\n\n", objectives = "" }
WordHunterWoW_QuestEN[13564] = { title = "A Lost Companion", description = "Please help... I can barely sit up.\n\nMy friend, a bear named Grimclaw, he's not here. I sent him ahead to let the Sentinels know we were coming before we left Auberdine, but he never arrived. I sensed something might be amiss as we were leaving, but with the evacuation, I never had a chance to act on it.\n\nIf he's injured, there's only one place that he would go - the Withering Thicket, north of Auberdine, down the road to the south from here. Bring him back to me safely... he's my only family.", objectives = "" }
WordHunterWoW_QuestEN[13565] = { title = "Twice Removed", description = "We cannot condone reckless violence - it is not our nature. However, there are times when the consequences of avoiding battle are too tangible to ignore, as is the case with these naga.\n\nWhen the earth in the area shattered, a small section of ruins rose to our east. These ruins once housed those loyal to Queen Azshara, and it seems her kind have returned in search of something.\n\nTake this petrified root. You can use it on their fallen to raise ents to aid you. Deal with them and their leader swiftly.", objectives = "" }
WordHunterWoW_QuestEN[13566] = { title = "Ritual Materials", description = "While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife.\n\nI need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly.\n\nI need hair from the doe to the east, just avoid the stags.\n\nFinally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating.\n\nPlease do not harm any of them.", objectives = "" }
WordHunterWoW_QuestEN[13567] = { title = "Spirit of the Stag", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Stag Spirit, take this incense to the woods just north of Bashal'Aran. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13568] = { title = "Spirit of the Moonstalker", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Moonstalker Spirit, take this incense to the land just south of the Ruins of Lornesta. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13569] = { title = "The Ritual Bond", description = "I will tend to Grimclaw until his rest is done - he will be ready to return very soon. I have one more task for you while we wait... a favor to grant you, really, should you recognize it.\n\nThe great wildlife spirits roam around us waiting and hoping for someone that will aid in stopping the destruction. They are with us as we speak even now, and with the materials  you brought me, I can grant you sight. Speak to these spirits, choose one, and return to me with their blessing.", objectives = "" }
WordHunterWoW_QuestEN[13570] = { title = "Remembrance of Auberdine", description = "", objectives = "" }
WordHunterWoW_QuestEN[13571] = { title = "Fletcher's Lost and Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[13572] = { title = "Jadefire Braziers", description = "The satyrs of Felwood have started pouring their hate and corruption into our lands. They have sent Sharax the Defiler to subdue parts of the forest that we Blackwood call home.\n\nIn addition to poisoning the land, animals, and plants, he has set up Jadefire braziers throughout the village to help extend his control over our people. Destroying the braziers alone won't be enough to stop him, but it will help lessen his influence while you work with Elder Brolg to free our brothers.", objectives = "" }
WordHunterWoW_QuestEN[13573] = { title = "Malfurion's Return", description = "It was only recently that we heard the news of Malfurion's awakening, mere moments before the Cataclysm occurred.\n\nAs soon as he regained consciousness, he gave a cryptic warning about the land splitting in two if something wasn't done and how all the shockwaves were converging here on Darkshore.\n\nHe then reportedly set off for somewhere in this vicinity.  I was sent here to find him, but I've found my hands full helping the refugees.\n\nPerhaps you could look for him to the southeast for us.", objectives = "" }
WordHunterWoW_QuestEN[13575] = { title = "The Land Is in Their Blood", description = "If we're to stabilize the forces of nature, we'll need every little bit of help we can get.  The furbolg of the Blackwood tribe have long inhabited the area and have strong ties to the land.\n\nTheir elder Shaman, Elder Brownpaw, wields great power over the elements -- his assistance would be invaluable.  See if you can obtain their aid.", objectives = "" }
WordHunterWoW_QuestEN[13576] = { title = "Mutual Aid", description = "With most of our brethren losing their way to madness or corruption, it would seem that we have little choice but to ally with you, {race}.  You can count on our aid... once you've proven we can count on yours.\n\nAs you can see, my people are having a bit of a problem with the fire elementals.  Help fight them and use this totem on their fiery remains.\n\nWe will return them to where they belong... whether they like it or not.", objectives = "" }
WordHunterWoW_QuestEN[13577] = { title = "The Last Wildkin", description = "The wildkin were once numerous in Darkshore.  Such are their ties to the land that the Cataclysm that shattered Darkshore also decimated their numbers.\n\nThe wildkin Aroom is the last of his tribe and is a powerful elder with a strong connection to Elune.  His help will be most necessary in healing the land -- you will find him north of here at the Moontouched Den.", objectives = "" }
WordHunterWoW_QuestEN[13578] = { title = "Aroom's Farewell", description = "<The creature hoots sadly as it addresses you.>\n\nAroom is last of tribe...\n\nOthers won't rest... need funeral pyre.  Bring Aroom the feathers of others.... let them rest.\n\nThen Aroom help you.", objectives = "" }
WordHunterWoW_QuestEN[13579] = { title = "Protector of Ameth'Aran", description = "Nothing will repair the land quicker than the strength of those who inhabit it.  We night elves are fortunate that some of our best allies just happen to be both the land and its inhabitants at once.\n\nThe Ancient of War known as Selenn was charged with guarding the ruins of Ameth'Aran, to the south.  Go there and seek his help.", objectives = "" }
WordHunterWoW_QuestEN[13580] = { title = "Soothing the Elements", description = "Their fiery spirits are contained in the totem now. Take it to the top of the overlook in the Blazing Strand and set it on the ground.\n\nThe totem's soothing energies will slowly wash over the elementals until their fury simmers down to calm.\n\nYou must protect the totem, for fire does not react favorably to the ritual of soothing.", objectives = "" }
WordHunterWoW_QuestEN[13581] = { title = "The Blackwood Pledge", description = "It won't be immediate, but the elementals' anger will soon die down and my people will live to fight another day.\n\nI will go help you and Malfurion in any way that I can.", objectives = "" }
WordHunterWoW_QuestEN[13582] = { title = "Elune's Fire", description = "We need special flame for ritual.  We need Elune's fire.\n\nHoroo's spirit wanders east of here.  Horoo carries torch of Elune.  Bring here so spirits rest.\n\nAroom thanks you.", objectives = "" }
WordHunterWoW_QuestEN[13583] = { title = "The Wildkin's Oath", description = "Wildkin with Elune.  Aroom in your debt now.\n\nAroom help you now.  Return to Malfurion, I join you soon.", objectives = "" }
WordHunterWoW_QuestEN[13584] = { title = "Calming the Earth", description = "I would be neglecting my responsibility if I abandoned my post just now, with so many elementals out of control in the ruins.\n\nLet us deal with them first, before we see how we can aid Malfurion.  What do you say, small one?", objectives = "" }
WordHunterWoW_QuestEN[13585] = { title = "Sworn to Protect", description = "My duty here has been fulfilled as best it can.  Send word to Malfurion that I'll be joining him soon.\n\nGood luck to you, {name}.  Good luck to all of us.", objectives = "" }
WordHunterWoW_QuestEN[13586] = { title = "The Emerald Dream", description = "Our efforts in containing the destruction don't appear to be quite enough.  I fear we're going to need aid from beyond the waking world.\n\nTwilight cultists inside the Earthshatter Cavern to the east have opened a gateway to a nightmare-infested section of the Emerald Dream.  They hold a green dragon prisoner named Thessera there.\n\nGo through the nightmare portal and free her.  She will be a powerful ally.", objectives = "" }
WordHunterWoW_QuestEN[13587] = { title = "The Waking Nightmare", description = "Malfurion's words are true, small one.  The rift that threatens to split Darkshore in half also threatens the separation between this world and yours.\n\nLet me aid you in any way that I can, lest further rifts between our worlds amplify the destruction taking place in both places.\n\nFirst you must undo the shackles cast upon me by retrieving the emerald scroll from the nightmare guardian that roams the halls below.", objectives = "" }
WordHunterWoW_QuestEN[13588] = { title = "The Eye of All Storms", description = "Twilight riders circle the skies above the vortex.  I fear it is their magic that has kept the cataclysmic forces from being contained by our efforts.\n\nTake to the skies with Thessera and destroy the riders and the portal from whence they came.", objectives = "" }
WordHunterWoW_QuestEN[13589] = { title = "The Shatterspear Invaders", description = "If we didn't have enough on our hands with the land and the elements turning against us, it seems something has riled up the trolls to the northeast, and they've started on a war path. I'm not sure what their aims are, but they've already attacked several of our scouts and have besieged the cultists at the Tower of Althalaxx.\n\nWe've sent a contingent of our best Sentinels to counter their attacks. If you would travel northeast to the ruins and join them, I'm certain that they could use the extra hand.", objectives = "" }
WordHunterWoW_QuestEN[13590] = { title = "The Front Line", description = "Their forces are weakened, their supplies destroyed, and their subleaders are dead. It is time for us to take this fight to their home, and their leader. I'm admittedly still in the dark as to what spurred their sudden aggression, but perhaps we will find some answers on their doorstep.\n\nTake this arrow that Balthule prepared and report to Sandrya Moonfall deep in Shatterspear Vale to join the attack. It would be best to secure a ride on one of our nightsabers - going on foot would be dangerous.", objectives = "" }
WordHunterWoW_QuestEN[13591] = { title = "Disturbing Connections", description = "The letter from Garrosh Hellscream makes clear the suspicions that were raised during the offensive on the Shatterspear. The presence of forsaken at the tower ruins and horde supplies and enforcers at the Shatterspear War Camp were only the start. Garrosh himself contacted the Shatterspear to spur their offensive towards Lor'danel, and it seems clear that he fully intends to push from the south as well.\n\nGlynda Nal'Shea will need this information if the night elves are to be prepared.", objectives = "" }
WordHunterWoW_QuestEN[13592] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "" }
WordHunterWoW_QuestEN[13593] = { title = "Valiant Of Stormwind", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13594] = { title = "Don't Forget the Horde", description = "Evenar and the other apprentices may not be much use in a battle, but you look like you can more than hold your own. The Horde scum across the road to the east at Bathran's Haunt need to be taught a lesson.\n\nTheir new warlord, Garrosh Hellscream, has them up to no good. Feel like teaching them a thing or two?\n\nI'd come with you, but my assignment is to stay here and protect Orendil's apprentices, and that's exactly what I'm going to do.", objectives = "" }
WordHunterWoW_QuestEN[13595] = { title = "Of Their Own Design", description = "These creatures... these so-called Horde... they have cut me down in my prime and they are harvesting my hair for their evil plans.\n\nWill you help me to put an end to it, little {race}?\n\nI have overheard their herbalists speaking of something called wildfire upon their table across the way. If you were to take the bottle of this unnatural stuff and throw it at my corpse to the northeast, it would burn and no more of my hair will grow here.\n\nI am already dead and it is a small price to pay to stop them.", objectives = "" }
WordHunterWoW_QuestEN[13596] = { title = "Twilight Plans", description = "We're not fully aware of the intentions of the Twilight's Hammer cultists to the southwest.  We fear an attack on Lor'danel, however their motives might go well beyond that.\n\nI need you to go to the Twilight Encampment and get your hands on their plans.  Hurry, {name}.  We might not have much time.", objectives = "" }
WordHunterWoW_QuestEN[13597] = { title = "Spirit of the Thistle Bear", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Thistle Bear Spirit, take this incense to a cave just east of the great whirlpool. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13598] = { title = "Unsavory Remedies", description = "I have no doubts that Grimclaw will recover with the help of my healing magics, though I can't say the same for the poachers that attacked him. Still, I could use some salve to close his wounds and lessen his pain while he heals.\n\nTo the east you will find the Ruins of Lornesta. Among the crumbled stones, there is a variety of fuming toadstool that flourishes in the damp environment. Bring me some of the toadstools so that I can mix a salve for our friend here.", objectives = "" }
WordHunterWoW_QuestEN[13599] = { title = "Grimclaw's Return", description = "With the binding complete, the blessing has taken hold. It will most certainly make your travels in these lands easier.\n\nGrimclaw made a full recovery. Before I could do anything to stop him, he bolted off towards Lor'danel. I suppose that means it's time for your departure.\n\nIt was a great pleasure to have met you. For now, farewell - send my best wishes to Volcor and Grimclaw.", objectives = "" }
WordHunterWoW_QuestEN[13600] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "" }
WordHunterWoW_QuestEN[13601] = { title = "In Aid of the Refugees", description = "By Elune!  It appears that many of those we feared dead from the attack on old Auberdine have taken refuge in a camp outside the town ruins.\n\nThe cultists at the Twilight Encampment were planning on making quick work of them.  It's a good thing that you successfully attacked their position.\n\nSeek out Priestess Alinya at the Refugee Camp east of old Auberdine and far south of here.", objectives = "" }
WordHunterWoW_QuestEN[13602] = { title = "Naga of the Strand", description = "There is evil lurking on the coast to the west.\n\nThe Zoram Strand is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas. It has been lost to the night elves for ages. Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know. But reason matters little; we must slay these fiends and throw them back to the depths!", objectives = "" }
WordHunterWoW_QuestEN[13603] = { title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "" }
WordHunterWoW_QuestEN[13604] = { title = "Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", objectives = "" }
WordHunterWoW_QuestEN[13605] = { title = "The Last Refugee", description = "There was this massive earthquake and then everything went black. The next thing I know, I woke up here a prisoner. The whole place is overrun with air elementals!\n\nI hope that everyone's okay. These Twillight's Hammer scum better not have hurt any of my friends!\n\nQuick, {class}, use something sharp to jimmy the lock on this ball and chain. Together we should be able to make it to the refugee camp.", objectives = "" }
WordHunterWoW_QuestEN[13606] = { title = "Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", objectives = "" }
WordHunterWoW_QuestEN[13607] = { title = "The Celestial Planetarium", description = "Listen, lad!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", objectives = "" }
WordHunterWoW_QuestEN[13609] = { title = "Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", objectives = "" }
WordHunterWoW_QuestEN[13610] = { title = "Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", objectives = "" }
WordHunterWoW_QuestEN[13611] = { title = "Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", objectives = "" }
WordHunterWoW_QuestEN[13612] = { title = "Mor'shan Defense", description = "Lok'tar, {race}!\n\nThe campaign is finally underway! Soon, all of Ashenvale will be in the grip of the Horde.\n\nAs we expected, our offensive is forcing the enemy to test our defenses at every position.\n\nHere at Mor'shan, their assault has been decimated! But as the vice tightens, they will have no choice but to continue to press us here.\n\nScout the region, {class}. Search for night elf survivors and cut them down before they can regroup for another assault!", objectives = "" }
WordHunterWoW_QuestEN[13613] = { title = "Rescue the Fallen", description = "Our forces are holding up admirably, {class}.\n\nBe that as it may, there are yet wounded to attend to - many still in the field of battle.\n\nI have created a salve that should grant the wounded enough energy to return to the ramparts for treatment. Please administer it to any in need before they become lost to us.", objectives = "" }
WordHunterWoW_QuestEN[13614] = { title = "Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, lad.  Time is of the essence.", objectives = "" }
WordHunterWoW_QuestEN[13615] = { title = "Empty Quivers", description = "Greetings, {class}, and welcome to the Ramparts.\n\nThings may appear a little chaotic here but do not worry. Kadrak has this juncture sealed up tight. Not a single elf has breached our lines!\n\nWhile you're here... I'm expecting a shipment of fresh supplies from Orgrimmar any day, but our watchmen are running dangerously low on arrows.\n\nBring me any you find and I will make it worth your trouble.", objectives = "" }
WordHunterWoW_QuestEN[13617] = { title = "West to the Strand", description = "{name}, I have a friend who could make good use of particular talents. His name is Talen and he's an archaeologist of sorts. Recently he's been fascinated with the upheaval of the old city of Zoram and its treasures.\n\nIf you're willing to lend him a hand, you can find him at the Blackfathom Camp down the path to the west.", objectives = "" }
WordHunterWoW_QuestEN[13618] = { title = "Find Gorat!", description = "Gorat is one of the Horde's most adept assassins.\n\nThe mere mention of his name strikes fear into the hearts of our Alliance foes.\n\nHe is reliable, fiercely loyal, and - until now - punctual.\n\nSomething's not right, {class}.\n\nGorat's mission was to find and eliminate the elf in charge of this assault on the ramparts.\n\nHe should be somewhere in the region of Fallen Sky Lake.\n\nFind him!", objectives = "" }
WordHunterWoW_QuestEN[13619] = { title = "Final Report", description = "<Gorat coughs deeply as he strains to speak.>\n\nIt was... an ambush....\n\nWe were... returning to the ramparts. All of us... lost....\n\nWe... discovered their leader... \n\n<Gorat painstakingly fills a vial with the blood spilling from one of his wounds.>\n\nMy men... must be avenged.... Bring this... to Kadrak....\n\nHe will know what to do....\n\n<Gorat expires.>", objectives = "" }
WordHunterWoW_QuestEN[13620] = { title = "To Dinah, at Once!", description = "The Horde may have never known one more loyal than Gorat. He never failed to complete a mission, and it would seem that he refuses to allow this to be his first.\n\nGorat had you deliver this vial for a purpose. Dinah is the daughter of a revered shaman, and is more powerful than she appears. Bring her the vial and hope that we are not too late.", objectives = "" }
WordHunterWoW_QuestEN[13621] = { title = "Gorat's Vengeance", description = "Fortune is with us this day, {race}.\n\nGorat's blood was fresh enough for me to conduct a special ritual taught to me as a child.\n\nUse this imbued blood on Gorat's corpse to summon forth his lingering spirit.\n\nDo his final bidding, then report back here to Kadrak.\n\nSpirits keep you safe, friend.", objectives = "" }
WordHunterWoW_QuestEN[13622] = { title = "Ancient History", description = "The pieces fit together to form an elegant hammer.  Its construction appears to be at least partially Titan in nature.\n\nThe console inside the Archivum might have some information regarding this artifact.", objectives = "" }
WordHunterWoW_QuestEN[13623] = { title = "Delivery for Orendil", description = "Quickly, {name}. I will put the Bathran's Hair into this bag, but you must deliver it to my master, Orendil Broadleaf. You will find him at Maestra's Post, just south down the road on the left.\n\nBut beware, we've received reports that the post is under attack from the Horde!", objectives = "" }
WordHunterWoW_QuestEN[13624] = { title = "A Squad of Your Own", description = "I certainly hope that you're here to help, {class}. The situation is as dire as it appears. To put it quite simply, we are losing!\n\nMy girls and I are the last line of defense against the Horde, but we're not going to get out of this one without taking the fight to them. Up for a challenge?\n\nI have a small squad of sentinels that I can loan to you. Get them close and I'm certain that their magic arrows can destroy those wreckers and invaders.\n\nSpeak to me again if you need replacements.", objectives = "" }
WordHunterWoW_QuestEN[13625] = { title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies. ", objectives = "" }
WordHunterWoW_QuestEN[13626] = { title = "Respect for the Fallen", description = "There were two humans here: Feero Ironhand and Delgren the Purifier. They were members of a holy organization known as The Argent Dawn. Both fell defending the post when the Horde first attacked.\n\nI'm going to loan you my magical cloak. It was a gift from Cenarius that allows me to move invisibly.\n\nFind both of their corpses and retrieve Feero's hammer and Delgren's prayer book. Feero's corpse is in the courtyard and Delgren's is atop the tower.\n\nBeware, the warlock up there will be able to see you.", objectives = "" }
WordHunterWoW_QuestEN[13627] = { title = "Jack Me Some Lumber", description = "Come closer. No, not too close. Don't want any unnecessary suspicion now, do we?\n\nThis coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!", objectives = "" }
WordHunterWoW_QuestEN[13628] = { title = "Got Lumber?", description = "Kadrak has just received fresh orders for our troops. I hear we're to begin offensive strikes into Ashenvale!\n\nI have far too few supplies to support an assault, and my shipment from Orgrimmar has yet to arrive.\n\nI am forced to  improvise, and could use your help, {class}.\n\nSpeak with Kadrak and ask him for the reins to Brutusk. The kodo will take you to the Warsong Labor Camp. Once there, seek out Gorka and ask her to load you up with logs.", objectives = "" }
WordHunterWoW_QuestEN[13629] = { title = "Val'anyr, Hammer of Ancient Kings", description = "The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr:  you must get the fragments inside the physical form of the being known as Yogg-Saron.\n\nIt sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.", objectives = "" }
WordHunterWoW_QuestEN[13630] = { title = "The Reason Why", description = "The furbolg have descended from the heights and overrun the Ruins of Ordil'Aran to the north. I believe they did so because they were attracted to what the dead cultists there uncovered:  three moonstones.\n\nLiladris Moonriver will counsel you to deal with the furbolg in a more direct manner, and I will not gainsay her, but I would ask that you go to the ruins and deactivate the moonstones.", objectives = "" }
WordHunterWoW_QuestEN[13631] = { title = "All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[13632] = { title = "Rear Guard Duty", description = "The moon priestess has a plan to make sure that no further furbolg descend upon us from the highlands. I am more concerned with those that are already at the ruins, some of which are massing just outside of the post.\n\nDistasteful as it may be, I must ask that you head north into the Ruins of Ordil'Aran and slay the furbolg. We cannot fight on two fronts!\n\nThank you, {class}.", objectives = "" }
WordHunterWoW_QuestEN[13633] = { title = "The Black Knight of Westfall?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.", objectives = "" }
WordHunterWoW_QuestEN[13634] = { title = "The Black Knight of Silverpine?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?", objectives = "" }
WordHunterWoW_QuestEN[13635] = { title = "South Gate Status Report", description = "We're due for sending a status report over to the mountaineers in the Valley of Kings.\n\nI expect you're on your way there next anyhow - would you mind dropping it off for me? Just take the tunnel to the east, and check in at the guard station. Hand it directly to Captain Rugelfuss.", objectives = "" }
WordHunterWoW_QuestEN[13636] = { title = "Stormpike's Orders", description = "I need to get some orders up to Mountaineer Stormpike at his post in Algaz Station. If you wouldn't mind taking them, just follow the road all the way up to the northwest and you'll be sure to see the main bunker.\n\nIf you'd like to lend a hand in accomplishing his tasks, we'd be glad to reward you for that as well.", objectives = "" }
WordHunterWoW_QuestEN[13639] = { title = "Resupplying the Excavation", description = "Ironband has an excavation to the southeast and he's been needing a hefty amount of explosives sent from the league for all the carving. Huldar, Miran, and Saean just departed with the most recent load and could probably use a hand.\n\nThey can't have made it very far, strong as they are. They can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch. Go catch up with them and help'm out, will ya?", objectives = "" }
WordHunterWoW_QuestEN[13640] = { title = "Management Material", description = "Truun needs wood, huh? Normally I could provide, but not today.\n\nWith constant elf attacks, gathering lumber is dangerous work. The peons I have left are reluctant to venture into the woods.\n\nYou want wood? Then you go convince the peons to work.\n\nAnd keep them safe! I cannot afford to lose any more!", objectives = "" }
WordHunterWoW_QuestEN[13641] = { title = "The Seer's Crystal", description = "Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights.\n\nI know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, {name}, and bring me the crystal it holds.", objectives = "" }
WordHunterWoW_QuestEN[13642] = { title = "Bathed in Light", description = "The concoction is not quite complete; it must be bathed within the Light of Elune before we can even think about giving it to the child.\n\nThere is a known location just to the west at Lake Falathim where the goddess's moonlight always touches down, day or night. Please, {name}, I implore you for the sake of Relara, take the concoction and bathe it in Elune's radiance.\n\nBut beware, strange things have befallen the area of the lake, and I fear that it is no longer safe to go there.", objectives = "" }
WordHunterWoW_QuestEN[13643] = { title = "The Stories Dead Men Tell", description = "The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip.\n\nIf indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, {name}, for we must be certain these deaths were not accidental.", objectives = "" }
WordHunterWoW_QuestEN[13644] = { title = "That Which Has Risen", description = "When I sensed these... things... rising from below, I came to put them back down. I found the corpse of your friend and dragged him as far as I could before one of my fetlocks was broken. It is all that I can do to hold off these foul tendrils.\n\nThere is one that controls the tendrils and eyes. It calls itself Harbinger Aphotic -- I'm sure that you have heard it yelling from the south.\n\nThe harbinger stands out of range of my magic, but you could get to him. If you dare....", objectives = "" }
WordHunterWoW_QuestEN[13645] = { title = "To Raene Wolfrunner", description = "I would ask you to deliver the gem directly to Raene Wolfrunner. Last I heard, she was still in Astranaar to the southeast.\n\nAt least the road between here and there is still relatively safe, so it should be a simple matter of following it there. Of course, if you'd rather, I believe that Sentinel Avana would be willing to loan you one of her nightsabers to swiftly make the trip.\n\nWhatever you choose, good health to you, {name}. May our paths cross again soon.", objectives = "" }
WordHunterWoW_QuestEN[13646] = { title = "Astranaar Bound", description = "You have been of great assistance to us, {name}. Without you, we would have been wiped out by now.\n\nIt would be my pleasure to offer you one of my nightsabers anytime to ride to Astranaar up and to the southeast. I'm sure that you have very important business to attend to there.\n\nI would consider it a great kindness if you would speak with my sister, Sentinel Luara, when you arrive to tell her that I am well.\n\nJust speak to me again when you are ready to go, and anytime that you need a ride it is yours.", objectives = "" }
WordHunterWoW_QuestEN[13647] = { title = "Joining the Hunt", description = "Well, you definitely have some fight in you.\n\nYou know, there are some hunter types at the lodge east of here, up in the hills - they might be right up your alley. Why don't you go pay them a visit and see if they have any work that you might be interested in?", objectives = "" }
WordHunterWoW_QuestEN[13648] = { title = "WANTED: The Dark Iron Spy", description = "A dark iron spy has infiltrated the town, stolen documents from the Explorers' League establishment, and is now in hiding somewhere nearby. He was last sighted near the top of the hill to the south of town.\n\nA sizable reward awaits anyone who can bring this spy to justice. Dead or alive - dead preferred.", objectives = "" }
WordHunterWoW_QuestEN[13650] = { title = "Keep Your Hands Off The Goods!", description = "We've uncovered some incredible artifacts at this site. It's hard to be convinced that it's all authentic, but there could be serious historical potential.\n\nUnfortunately, when the troggs overran the site, we lost access to three of our most notable finds to date. I'm concerned that the troggs might have stolen them or defiled them in our absence.\n\nIf you go into the excavation, find the Upturned Giant, the Overdressed Woman, and the Broken Tablet, and make sure they're still intact.", objectives = "" }
WordHunterWoW_QuestEN[13651] = { title = "Needs a Little Oil", description = "You have your wood, but the encroaching elves have made it impossible for your kodo to return to Mor'shan Ramparts.\n\nI've dispatched a runner to Splintertree to summon aid. It shouldn't take long for their forces to clear the way.\n\nIn the meantime, I would ask that you do us a service. Rust has rendered our shredders inoperable. A little lubrication and they'll be as good as new.\n\nThe oil from the rotting slimes just north of here should work just fine.", objectives = "" }
WordHunterWoW_QuestEN[13653] = { title = "Crisis at Splintertree", description = "There will be no help coming from Splintertree.\n\nThe elves have launched a major assault on our stronghold there and they have the place surrounded!\n\nWe must inform Kadrak or die trying!\n\nYour kodo has been loaded up with the wood you collected. Let me know when you're ready and we'll charge the enemy lines.", objectives = "" }
WordHunterWoW_QuestEN[13654] = { title = "There's Something About the Squire", description = "Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs.\n\nHe usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight.\n\nFind a way to distract or incapacitate him and search him. If he's up to something, we'll know it.", objectives = "" }
WordHunterWoW_QuestEN[13655] = { title = "Explorers' League Document (2 of 6)", description = "The document bears the Explorers' League crest and seems to detail potential dig sites in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13656] = { title = "Explorers' League Document (1 of 6)", description = "The document bears the Explorers' League crest and contains extensive information on the indigenous creatures of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13657] = { title = "Explorers' League Document (3 of 6)", description = "The document bears the Explorers' League crest and contains historical records for all the notable locations in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13658] = { title = "Explorers' League Document (4 of 6)", description = "The document bears the Explorers' League crest and seems to detail transport routes utilized by the league into and out of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13659] = { title = "Explorers' League Document (6 of 6)", description = "The document bears the Explorers' League crest and contains detailed assessments of the various threats present within Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13660] = { title = "Explorers' League Document (5 of 6)", description = "The document bears the Explorers' League crest and contains a detailed list of the artifacts excavated by Ironband's workers in southeastern Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", objectives = "" }
WordHunterWoW_QuestEN[13661] = { title = "Heartfelt Appreciation", description = "You located all of our documents! We can't think you enough for the help... we'd all but given up hope that the dark irons would be able to act upon all of this information soon. It's good to know that they'll be left blind in their attacks for quite a while yet.\n\nTo thank you for all of your efforts on our behalf, we would like to offer you a gift. An artifact really... something we recovered from one of our digs. You have the appreciation of all of the Explorers' League.", objectives = "" }
WordHunterWoW_QuestEN[13663] = { title = "The Black Knight's Orders", description = "We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors.\n\nThe Kirin Tor has offered to help in this matter and provided us with something to help our search.\n\nTake this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon. The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.", objectives = "" }
WordHunterWoW_QuestEN[13664] = { title = "The Black Knight's Fall", description = "We must put an end to the Black Knight's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered.\n\nBy now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, {name}.\n\nUse my argent charger for the battle. It's housed in the stables.\n\nSpeak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.", objectives = "" }
WordHunterWoW_QuestEN[13665] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.\n\n", objectives = "" }
WordHunterWoW_QuestEN[13666] = { title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "" }
WordHunterWoW_QuestEN[13667] = { title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nArcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.", objectives = "" }
WordHunterWoW_QuestEN[13668] = { title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nMagister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.\n", objectives = "" }
WordHunterWoW_QuestEN[13669] = { title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "" }
WordHunterWoW_QuestEN[13670] = { title = "The Edge Of Winter", description = "The Ironforge grand champion's squire told me an intriguing story.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13671] = { title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[13672] = { title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13673] = { title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "" }
WordHunterWoW_QuestEN[13674] = { title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "" }
WordHunterWoW_QuestEN[13675] = { title = "The Edge Of Winter", description = "I heard an interesting story from one of the Orgrimmar valiants.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13676] = { title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[13677] = { title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies. \n", objectives = "" }
WordHunterWoW_QuestEN[13678] = { title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", objectives = "" }
WordHunterWoW_QuestEN[13679] = { title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against a skilled opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your horse be steady and your aim true.", objectives = "" }
WordHunterWoW_QuestEN[13680] = { title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against an experienced opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your mount be steady and your aim true.", objectives = "" }
WordHunterWoW_QuestEN[13681] = { title = "A Chip Off the Ulduar Block", description = "Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.'\n\nAnyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.", objectives = "" }
WordHunterWoW_QuestEN[13682] = { title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "" }
WordHunterWoW_QuestEN[13683] = { title = "Stopping the Rituals", description = "I could not help but overhear Illiyana's loss. I understand her need for revenge. I am wondering if while you are exacting it, you could do us a service?\n\nNo doubt you have already seen the satyr of Satyrnaar and Xavian conducting vile rituals. I believe that they are preparing their rituals to corrupt any of the night elves they capture, turning them into satyrs. We draenei also have problems with fel magic exposure.\n\nWould you disturb their ritual gems while you are there?", objectives = "" }
WordHunterWoW_QuestEN[13684] = { title = "A Valiant Of Stormwind", description = "You've proven yourself worthy of competing under the banner of Stormwind, {name}. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13685] = { title = "A Valiant Of Ironforge", description = "You've proven yourself worthy of competing under the banner of Ironforge, {name}. Now, you should introduce yourself to Lana Stouthammer, who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13688] = { title = "A Valiant Of Gnomeregan", description = "You've proven yourself worthy of competing under the banner of Gnomeregan, {name}. Now, you should introduce yourself to Ambrose Boltspark, who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13689] = { title = "A Valiant Of Darnassus", description = "You've proven yourself worthy of competing under the banner of Darnassus, {name}. Now, you should introduce yourself to Jaelyne Evensong, who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13690] = { title = "A Valiant Of The Exodar", description = "You've proven yourself worthy of competing under the banner of the Exodar, {name}. Now, you should introduce yourself to Colosos, who leads the Exodar delegation. As the draenei grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13691] = { title = "A Valiant Of Orgrimmar", description = "You've proven yourself worthy of competing under the banner of Orgrimmar, {name}. Now, you should speak with Mokra the Skullcrusher, who leads Orgrimmar's competitors. As Orgrimmar's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13693] = { title = "A Valiant Of Sen'jin", description = "You've proven yourself worthy of competing under the banner of Sen'jin, {name}. Now, you should speak with Zul'tore who leads Sen'jin's warriors. As the troll grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13694] = { title = "A Valiant Of Thunder Bluff", description = "You've proven yourself worthy of competing under the banner of Thunder Bluff, {name}. Now, you should speak with Runok Wildmane, who leads Thunder Bluff's competitors. As Thunder Bluff's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13695] = { title = "A Valiant Of Undercity", description = "You've proven yourself worthy of competing under the banner of the Undercity, {name}. Now, you should speak with Deathstalker Visceri, who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13696] = { title = "A Valiant Of Silvermoon", description = "You've proven yourself worthy of competing under the banner of Silvermoon, {name}. Now, you should speak with Eressea Dawnsinger, who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", objectives = "" }
WordHunterWoW_QuestEN[13697] = { title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", objectives = "" }
WordHunterWoW_QuestEN[13698] = { title = "Explosives Shredding", description = "I hate to send you back in there, but based on your description of what's going on, we can't let them use all of those explosives they have stored up!\n\nIt's too dangerous for you to try to destroy them yourself, but if you were to steal one of their shredders, I'm sure they're tough enough to withstand the explosions.\n\nAfter you've destroyed their explosives, return here with the shredder. There's no sense in letting them have it back.", objectives = "" }
WordHunterWoW_QuestEN[13699] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "" }
WordHunterWoW_QuestEN[13702] = { title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13703] = { title = "Valiant Of Ironforge", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13704] = { title = "Valiant Of Gnomeregan", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a {class} like you.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13705] = { title = "Valiant Of The Exodar", description = "Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13706] = { title = "Valiant Of Darnassus", description = "Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13707] = { title = "Valiant Of Orgrimmar", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13708] = { title = "Valiant Of Sen'jin", description = "Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13709] = { title = "Valiant Of Thunder Bluff", description = "Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13710] = { title = "Valiant Of Undercity", description = "Welcome, champion. The Forsaken delegation could always use more {class}s like you. Would you join us?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13711] = { title = "Valiant Of Silvermoon", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.", objectives = "" }
WordHunterWoW_QuestEN[13712] = { title = "To the Rescue!", description = "You're coming with me, {name}.\n\nThere's no one else that I can spare, and we cannot afford for Splintertree to be lost.\n\nPrepare yourself, and speak to me again when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[13713] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "" }
WordHunterWoW_QuestEN[13714] = { title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", objectives = "" }
