WordHunterWoW_QuestEN[13730] = { title = "Playing With Felfire", description = "<Draaka leans down to speak to you.>\n\nListen... Before you say anything, I KNOW we're not to meddle with demonic energies....\n\nBut look around you! These are desperate times, {class}.\n\nWe'll most likely die here, regardless. May as well go out in a blaze of glory, I say!\n\nSo... Are you in?\n\nTake this canister and go southeast to Felfire Hill. Use it near the patches of felfire and bring it back to me when you've filled it.\n\nOh, and best not to mention this to anyone....", objectives = "" }
WordHunterWoW_QuestEN[13731] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "" }
WordHunterWoW_QuestEN[13732] = { title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", objectives = "" }
