WordHunterWoW_QuestEN[13735] = { title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13736] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Orgrimmar!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13737] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Darkspear!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13738] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Thunder Bluff!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13739] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Forsaken!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13740] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Silvermoon!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "" }
WordHunterWoW_QuestEN[13741] = { title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "" }
WordHunterWoW_QuestEN[13742] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "" }
WordHunterWoW_QuestEN[13743] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13744] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "" }
WordHunterWoW_QuestEN[13745] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Ironforge are looking forward to hearing of our success. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same. The valiants practice in the ring just outside our tent. Equip your lance, go to the stables outside the pavilion and mount the stabled Ironforge ram, then challenge other Alliance valiants.\n", objectives = "" }
WordHunterWoW_QuestEN[13746] = { title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "" }
