WordHunterWoW_QuestEN[13750] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. We know everyone's looking forward to seeing us in the competition. To that end, we've been honing our skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.\n", objectives = "" }
WordHunterWoW_QuestEN[13751] = { title = "Tell No One!", description = "Perfect!\n\nThis will show the elves what the Horde is capable of when we're backed into a corner.\n\nListen, {name}. You must say nothing of this to anyone!\n\nSaurfang will surely approve once he sees the results, but if we are found out beforehand, our heads will be placed on spikes!\n\n<Draaka hands you a hastily written note.>\n\nBring this to Durak. You can find him in the mines behind me, just to the north. He will instruct you further.", objectives = "" }
