WordHunterWoW_QuestEN[13786] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "" }
WordHunterWoW_QuestEN[13787] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Silvermoon hawkstrider, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.\n\n", objectives = "" }
WordHunterWoW_QuestEN[13788] = { title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "" }
WordHunterWoW_QuestEN[13789] = { title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter. ", objectives = "" }
WordHunterWoW_QuestEN[13790] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses to you.\n\nIt would be wise to continue practicing your skills against the combatants waiting in the Ring of Champions. Equip your lance, go to the stables on the southern side of the grounds. then mount up on any mount you're permitted to use, and face the champions.", objectives = "" }
WordHunterWoW_QuestEN[13791] = { title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", objectives = "" }
WordHunterWoW_QuestEN[13792] = { title = "The Shadewalker", description = "Now that the demon gates have been destroyed, the power of the forest must be replenished. The Forest Heart must be retrieved!\n\nGaivan Shadewalker, a powerful druid of the claw, has gone southwest, past Felfire Hill, to the Dor'Danil Barrow Den. Therein rests the Forest Heart. It is protected by the druids of Ashenvale deep below the ground.\n\nSeek out Gaivan and tell him of what has transpired, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13793] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, and pick any mount you're permitted to ride, then face the champions.", objectives = "" }
WordHunterWoW_QuestEN[13794] = { title = "Eadric the Pure", description = "I have asked my brothers of the Argent Crusade to work closely with those who rise to the rank of champion. Eadric the Pure, our brotherhood's grand champion, helps oversee training exercises for champions from all cities and helps them make their final preparations for tournament competition.\n\nPlease go and introduce yourself to him. I know he'll be eager to meet you and work with you on your way to competing against Azeroth's greatest champions.", objectives = "" }
WordHunterWoW_QuestEN[13795] = { title = "The Scourgebane", description = "The leader of the Knights of the Ebon Blade delegation has asked to speak you, {class}. Crok Scourgebane is as fearsome a combatant as they come and I have no doubt he'll have much to ask of you.\n\nThe Knights of the Ebon Blade have made camp on the north side of the tournament grounds, west of the tent housing the Alliance delegations.", objectives = "" }
WordHunterWoW_QuestEN[13796] = { title = "The Forest Heart", description = "You must get the Forest Heart to Gnarl at all costs!\n\nDown at the bottom of the Dor'Danil Barrow Den it sits, corrupted by the Horde. Only Gnarl can cleanse it.\n\nIn order to move it, though, you'll need a Power of Nature. If you collect enough untainted spirits from the Severed druids and keepers, the spirits can be combined into a Power of Nature.\n\nGood luck, {name}!", objectives = "" }
WordHunterWoW_QuestEN[13797] = { title = "Dirty Deeds", description = "What Draaka requires is a magnet of sorts - something that her demonic missiles will be drawn to.\n\n<Durak grins slyly.>\n\nI happen to know of a method that should suit our purposes.\n\nYou scour the mines for fist-sized chunks of ore, while I prepare a special... enchantment.", objectives = "" }
WordHunterWoW_QuestEN[13798] = { title = "Rain of Destruction", description = "Just in time, {class}. The elves have launched another attack!\n\nFrom the guard towers, use the accursed ore to mark targets for Draaka.\n\nHer projectiles will strike your target and erupt in fel magic flame, destroying any nearby enemies.\n\nThere is strong prejudice against the use of demonic magics. Unjustified, but real nonetheless. For this reason, I will transform you into an imp for the duration of the mission to prevent you from being identified.", objectives = "" }
WordHunterWoW_QuestEN[13801] = { title = "Dead Elves Walking", description = "D-did you hear that? Ghosts! I hate ghosts!\n\nTheir eerie howls are coming from the barrows to the south. Ahhh! Make them stop!!\n\nPlease, mister I'll pay good money to get those voices out of my head!", objectives = "" }
WordHunterWoW_QuestEN[13803] = { title = "Blood of the Weak", description = "We knew the elves wouldn't go down without a fight, but no one expected them to be able to lay siege to Splintertree...\n\nTime for them to pay for their actions!\n\nNearby, in the Dor'Danil Barrow Den, lies something very dear to the enemy - the Forest Heart.\n\nI need someone to make their way to the heart and corrupt it.\n\nThat someone is you, {name}.\n\nFirst though, bring my axe to Durak here in the mines. He'll make use of the blood of our enemies.", objectives = "" }
WordHunterWoW_QuestEN[13805] = { title = "Pierce Their Heart!", description = "There...\n\nThe blood of the fallen Kaldorei is turned. It can now be used on the Forest Heart in Dor'Danil Barrow Den. Doing so will utterly corrupt it.\n\nThe sacred relic of the arrogant elves will be turned against them. How poetic!\n\n<Durak laughs cruelly.>\n\nThe barrow den lies nestled against the hills to the southeast. One of my imps has laid a blood trail from the entrance to the heart.\n\nMake haste! Kadrak is not likely to be in a patient mood.\n\nOff you go, {class}.", objectives = "" }
WordHunterWoW_QuestEN[13806] = { title = "Demon Duty", description = "Listen, {class}, I know this assault on Splintertree has everyone worked up, but if we forget about the satyr portals we'll come out of this crisis to face an even larger one.\n\n<Locke stares at your expressionless face.>\n\nYou don't know about the portals?\n\nTo the northeast, in the regions of Satyrnaar and Xavian, the satyrs are attempting to summon in demons to bolster their numbers.\n\nWe must be vigilant in closing those portals, no matter what issues we face here!", objectives = "" }
WordHunterWoW_QuestEN[13808] = { title = "Mission Improbable", description = "I have a special mission that requires a well equipped, competent {class}. As I have no one else to spare, I suppose I'll have to settle for you...\n\nThe enemy has assaulted Warsong Lumber Camp and cut it off from the rest of our forces. An important blood elf diplomat en route to Orgrimmar is trapped there.\n\nShe must be liberated.\n\nTake the road northeast and light the smoldering brazier to summon our operative there. Do whatever he might require of you.\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[13809] = { title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "" }
WordHunterWoW_QuestEN[13810] = { title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter.", objectives = "" }
WordHunterWoW_QuestEN[13811] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses.\n\nIt would be wise to continue honing your own skills and learning from your opponents. Champions representing all cities practice in the Ring of Champions. Equip your lance, mount up on any mount you're entitled to use at the stables, and face the champions.", objectives = "" }
WordHunterWoW_QuestEN[13812] = { title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "" }
WordHunterWoW_QuestEN[13813] = { title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", objectives = "" }
WordHunterWoW_QuestEN[13814] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, pick any mount you can ride, then face the champions in practice bouts.", objectives = "" }
WordHunterWoW_QuestEN[13815] = { title = "Making Stumps", description = "As you've been told by now, we are to escort a diplomat from within the besieged lumber camp to safety.\n\nAs it stands, that's simply impossible. The elves have a thousand arrows trained on the camp's exits.\n\nFirst we must create a diversion - something that will take their eyes off of the camp for a time.\n\nMy idea is simple. Take this axe and cut down the trees they've been nurturing in the region.\n\nWhen you're through, light the brazier here to speak with me again.", objectives = "" }
WordHunterWoW_QuestEN[13816] = { title = "Heroic: The Celestial Planetarium", description = "Listen, lad!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", objectives = "" }
WordHunterWoW_QuestEN[13817] = { title = "Heroic: Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", objectives = "" }
WordHunterWoW_QuestEN[13818] = { title = "Heroic: Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, lad.  Time is of the essence.", objectives = "" }
WordHunterWoW_QuestEN[13819] = { title = "Heroic: All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[13820] = { title = "The Blastbolt Brothers", description = "The highlord has tasked me with getting that coliseum completed as soon as possible. We've put our own masons to work on the project, but we found out very quickly that we were going to need help procuring materials. I've hired a couple of goblins, Bezzle Blastbolt and his brother, Bozzle.\n\nThey're supervising construction at the southeastern end of the tournament grounds. Speak with Bezzle and see if he and his brother could use any more help getting the building materials we need.", objectives = "" }
WordHunterWoW_QuestEN[13821] = { title = "Heroic: Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", objectives = "" }
WordHunterWoW_QuestEN[13822] = { title = "Heroic: Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", objectives = "" }
WordHunterWoW_QuestEN[13823] = { title = "Heroic: Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", objectives = "" }
WordHunterWoW_QuestEN[13824] = { title = "Heroic: Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", objectives = "" }
WordHunterWoW_QuestEN[13825] = { title = "Clamlette Surprise", description = "", objectives = "" }
WordHunterWoW_QuestEN[13826] = { title = "Nat Pagle, Angler Extreme", description = "", objectives = "" }
WordHunterWoW_QuestEN[13828] = { title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", objectives = "" }
WordHunterWoW_QuestEN[13829] = { title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", objectives = "" }
WordHunterWoW_QuestEN[13830] = { title = "The Ghostfish", description = "Any Northrend angler worth his salt knows about the pygmy suckerfish.  It's not edible, but sometimes useful to alchemists.\n\nThere is, however, a stealthy fish that hides among the suckerfish in the River's Heart of Sholazar Basin.  The phantom ghostfish.  When out of water, they become increasingly translucent until they fade away completely.  Some hypothesize they return to Sholazar, and others are more... superstitious.\n\nI want you to catch this fish and discover its secret by any means!", objectives = "" }
WordHunterWoW_QuestEN[13831] = { title = "A Troubling Prescription", description = "A crude, hastily-assembled apothecary's workbench stands here, heaped with scrawled notes and noxious brews. It looks as though the Forsaken have also been studying Foulhoof's handiwork. You grab the most important-looking notes and prepare to smash the laboratory before notifying Treetender of your discovery.", objectives = "" }
WordHunterWoW_QuestEN[13832] = { title = "Jewel Of The Sewers", description = "Hard to believe that most people fish in the Dalaran Sewers for giant rats and mutated fish.  Especially when those waters are filled with priceless jewelry - discarded by broken hearted fools, thieves, and careless drunks.\n\nThe trick is to let your hook drag the bottom and don't pull up too hard when you get something.  Try it out, {name}.  I'd be willing to trade whatever you find for a few trinkets of my own.", objectives = "" }
WordHunterWoW_QuestEN[13833] = { title = "Blood Is Thicker", description = "The bloodtooth is a feisty little fish used in a recipe to cure infected wounds.  We could use some of them, if you're up to it.\n\nAs the name suggests, they've a hunger for blood.  The only way I know how to catch the little devils is by creating a blood pool and fishing in it.\n\nGet yourself covered in blood - just slaughter a beast in the Borean Tundra - and then jump in the water.  It'll wash right off and create the perfect fishing spot.", objectives = "" }
WordHunterWoW_QuestEN[13834] = { title = "Dangerously Delicious", description = "The best fishing is often the most dangerous.  Wintergrasp boasts a bountiful catch for the brazen.\n\nIn fact, it's the only place to catch the fabled Terrorfish - a fish both lethal and delicious.  Bring me some, and we'll have something to discuss.", objectives = "" }
WordHunterWoW_QuestEN[13835] = { title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", objectives = "" }
WordHunterWoW_QuestEN[13836] = { title = "Disarmed!", description = "I've received word of an unfortunate accident at the Dalaran prison; a guard had his arm severed and thrown into the water by a particularly vicious inmate.\n\nOur first aid clinic promises they can reattach the arm if we bring it back.\n\nYou fish long enough in the water outside the prison, and I'd bet my favorite fishing pole that arm will surface.  Find that arm, and bring it to Olisarra the Kind here in Dalaran.  She'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[13837] = { title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", objectives = "" }
WordHunterWoW_QuestEN[13838] = { title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", objectives = "" }
WordHunterWoW_QuestEN[13839] = { title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", objectives = "" }
WordHunterWoW_QuestEN[13841] = { title = "All Apologies", description = "This could be the end of me... Perhaps my actions were not thought out as well as they should have been...\n\nThe good news is that we pushed back an attack that would have otherwise meant the end of Splintertree. Let us pray that Saurfang sees it that way.\n\nI am certain to be summoned to Orgrimmar to explain my actions.\n\nPlease, {name}, go ahead of me and present this letter to his advisor Eitrigg.\n\nDo what you can to soften his heart towards me.", objectives = "" }
WordHunterWoW_QuestEN[13842] = { title = "Dread Head Redemption", description = "I sense that Durak is more than he seems. Demonic power is dangerous and it is easy to fall to its corruption - even for a trained warlock. \n\nI do not trust him, {name}.\n\nFind this Durak and tell him that the Horde will have nothing to do with him.", objectives = "" }
WordHunterWoW_QuestEN[13844] = { title = "The Looting of Althalaxx", description = "Before you rejoin the battle, {class}, something urgent has come to my attention. My scouts report that the Forsaken are scouring the ruined tower of Althalaxx to our south.\n\nPrior to the assault, that bleak tower housed a fanatical arm of the Shadow Council commanded by the fallen highborne Athrikus Narassin. Narassin is long since dead, but if any of his work survives, we can't allow it out of our sight. Retrieve his research and kill the Forsaken commander who's plundering the ruins.", objectives = "" }
WordHunterWoW_QuestEN[13846] = { title = "Contributin' To The Cause", description = "The bestest of the champions come to the chapel to hear the argent confessor speak every day.\n\nYou should see how much she inspires them, {name}. Not only do they fight for the Argent Crusade, but they put a lot of money into the collection basket when I take it around.\n\nMaybe you'd like to contribute too?", objectives = "" }
WordHunterWoW_QuestEN[13847] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13848] = { title = "Bad News Bear-er", description = "No reports have made it out of here since the beginning of the siege on Splintertree. By now, Commander Grimfang must be getting anxious.\n\nI am sending you to Zoram Strand to deliver our report. It's not pretty, but at least he'll have the facts.\n\nSpeak to Vhulgra when you're ready to make the trip.", objectives = "" }
WordHunterWoW_QuestEN[13849] = { title = "Astranaar's Burning!", description = "{class}, Astranaar's burning!\n\nQuickly, take this bucket of water and put out the fires before there's nothing left!", objectives = "" }
WordHunterWoW_QuestEN[13850] = { title = "Toxic Tolerance", description = "You want to ride a Venomhide? Then I've got bad news for you.\n\nThe Venomhide Ravasaurs, they're all poison: Poison blood, poison spit, poison skin. You climb on one, you fall off dead in a few hours.\n\nYou'd have to build up a resistance to their toxins before I sold you one, and that takes a long, LONG time... you'd need to be splashed with poisonous blood while fighting one numerous times. If you're really interested, the venomhides prefer the northern area of the Marshlands, northwest of here.", objectives = "" }
WordHunterWoW_QuestEN[13851] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13852] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13853] = { title = "Return Fire", description = "The fires are mostly contained, but we have to do something about those wind riders!\n\nQuick, {name}, you have to jump into one of our glaive throwers and return fire!", objectives = "" }
WordHunterWoW_QuestEN[13854] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
