WordHunterWoW_QuestEN[13861] = { title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13862] = { title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled argent charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13863] = { title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13864] = { title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "" }
WordHunterWoW_QuestEN[13865] = { title = "Wet Work", description = "Listen carefully, {class}.\n\nThere are three leaders in this region who are commanding the elves, keeping their focus directed on the lumber camp. Slaying them will certainly cause panic and disarray, hopefully enough for us to successfully complete our mission.\n\nWhile you're at it, bringing down their scouts can only aid our cause.", objectives = "" }
WordHunterWoW_QuestEN[13866] = { title = "To The Ramparts!", description = "These woods may be silent but our enemies lurk behind every trunk. I've discovered many an orc with arrows in his back, his weapon still sheathed.\n\nIt is treacherous here, behind the lines, but we could use strong arms and sharp minds down at the Mor'shan Ramparts. Kadrak is preparing an offensive from there - he prefers action to talk. You and he will get along.\n\nSpeak with me when you are ready and I will fly you there. ", objectives = "" }
WordHunterWoW_QuestEN[13867] = { title = "Culling the Furbolg Threat", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly!\n\nGo to Thistlefur Village and kill as many of their kind as you can.\n\nI shall remain here in Astranaar and await word from you. Elune be with you, {class}.", objectives = "" }
WordHunterWoW_QuestEN[13868] = { title = "Corrupting Influence?", description = "As you search through the belongings of the dead furbolg lying before you, a small charm, very obviously created by trolls,  spills out onto the ground.\n\nTouching the charm, you immediately get a sense that something is not right about the wood. A feeling of unease, of corruption, permeates the object.\n\nWrapping it in some spare cloth, you put it in your pack and resolve to show it to Raene Wolfrunner when next you find yourself in Astranaar.", objectives = "" }
WordHunterWoW_QuestEN[13869] = { title = "Recover the Remains", description = "While what the satyrs have done to the trees is horrible, nothing compares to the mass slaughter that the orcs have been engaging in!\n\n<The ancient shakes with visible rage, his leaves falling all around you.>\n\n{race}, I would have you head across the road here at the lumber camp and recover the remains of those trees, treants, and ancients that the Horde have hewn down in their prime.", objectives = "" }
WordHunterWoW_QuestEN[13870] = { title = "As Good as it Gets", description = "Well, {class}, this is as good as it gets.\n\nThe elves are scrambling to recover from your recent deeds. There's no better time to break into the lumber camp!\n\nMake your way in and speak with Overseer Gorthak. He'll instruct you as to how best escort the diplomat to safety.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[13871] = { title = "Security!", description = "It's not as like I haven't got enough to think about here!\n\nKeeping this place operational is hard enough without constant elf and draenei harassment.\n\nNow, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch!\n\nWhoever it is couldn't have gotten far, {class}. Scour the camp until you find her and then avenge the diplomat!\n\nAt least I can bring the assassin's head with me when I have to answer to Hellscream.", objectives = "" }
WordHunterWoW_QuestEN[13872] = { title = "Worgen Wisdom", description = "The man standing right across from me is known as Hephaestus Pilgrim. He's one of the worgen.\n\nHe and his sister came to Astranaar not long ago looking for a place to live. From what little I've been able to glean, he's interested in trying to help the Earthen Ring with the Cataclysm. His sister is even more powerful. She's gone east to try and help the shaman deal with the volcano.\n\nPerhaps he can help. Take the charm over to him and see what he thinks.", objectives = "" }
WordHunterWoW_QuestEN[13873] = { title = "Sheelah's Last Wish", description = "I... I cannot believe she's gone. It all happened so fast....\n\nI understand that I have you to thank for avenging my mistress. For that, you have my gratitude, and that of Silvermoon.\n\nIn her wisdom, my lady foresaw this end. She prepared a missive to be delivered in the event that something happened to her.\n\nWe were to join an Orgrimmar retinue at the crossroads just north of here. Please, {race}, meet them in our stead and see that the message is delivered.", objectives = "" }
WordHunterWoW_QuestEN[13874] = { title = "A Not-So-Charmed Life", description = "The furbolg covet that which does not belong to them.\n\n<Hephaestus turns the charm over in his hand and then discards it.>\n\nThere's a property to the carving that slowly corrupts those that aren't trolls. As I understand it, the furbolg have done this sort of thing before. Some never learn.\n\nNo doubt they hoard most of the charms in Thistlefur Hold above their village to the north.", objectives = "" }
WordHunterWoW_QuestEN[13875] = { title = "Gurtar's Request", description = "I have a bit of a personal request for you, {class}.\n\nIt has been many moons since I have seen my love, Draaka. It will be many more before we are able to be together again. I fear that as time passes, her love for me will wane.\n\nThis braid has special meaning to the two of us, as do Thorned Bloodcups, the flower of this region.\n\nI ask that you pluck the flowers and weave them into this twine, then present the gift to Draaka on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[13876] = { title = "Too Far Gone", description = "Yes, I speak your tongue, {race}.\n\nWe furbolg have been through this kind of corruption before. Not long ago our leader stole the Idol of Remulos. The demon-tainted thing ensorcelled the entire tribe and our redemption was barely delivered by a druid known as Broll Bearmantle.\n\nBut this time, we did not steal. The trolls of Zoram'gar gave us the charms as a sign of friendship. A deadly friendship it would seem.\n\nOur chief, Dal Bloodclaw, is too far gone. Enter the hold and return with his charms.", objectives = "" }
WordHunterWoW_QuestEN[13877] = { title = "Go With The Flow", description = "<The worgen stares at you intently before launching into his request.>\n\nThe volcano threatens to engulf all of Ashenvale if we do not act quickly. Let me assure you, this was no natural eruption.\n\nMy sister, Sabina, is powerful. She has gone east to the edge of Thunder Peak's lava flow, just north of the road to enlist the aid of the other elements against the fire lord that has caused this destruction.\n\n{name}, go to her and give her what assistance you can.", objectives = "" }
WordHunterWoW_QuestEN[13878] = { title = "Through Fire and Flames", description = "Help me, {class}! Piggy men come burn stables - fire! Fire!\n\n<Dorak wails incoherently before you can settle him down.>\n\nWolves still chained inside. Someone's got to save the wee wolves!  ", objectives = "" }
WordHunterWoW_QuestEN[13879] = { title = "Thunder Peak", description = "Greetings, {class}.\n\nCongratulations on your victorious assault on Astranaar. The elves shall not soon forget the humiliation they have suffered at your hand.\n\nBut you must know, the elves are not the only obstacle to the Horde's conquering of Ashenvale....\n\nTo the east, a shaman of the Earthen Ring requires assistance with yet another crisis. You can find him near the base of the volcano, Thunder Peak.", objectives = "" }
WordHunterWoW_QuestEN[13880] = { title = "Hot Lava", description = "<The massive earth elemental gazes down upon you.>\n\nThe flow of the lava must be stopped if we are to prevail. I will grant to you a portion of my power. Use it to fill the lava fissures!", objectives = "" }
WordHunterWoW_QuestEN[13881] = { title = "Consumed", description = "My first concern right now is for the thistle bear families who call what's left of these woods home. Just to our south, beyond the bear shrine, an entire generation has fallen ill. Gruesomely ill.\n\n{name}, I don't know what they're suffering from, but it's consumed them from within. It pains me that a whole generation is beyond saving, but we've got to kill them off so that the earth can reclaim their bodies.\n\nMore importantly, we need to find the source. Investigate the shallow lake they drink from!", objectives = "" }
WordHunterWoW_QuestEN[13882] = { title = "The Seeds of Life", description = "Something is trying to devour the life of Darkshore from within! I'll ask around to learn more about the - thing - you discovered in the lake. Meanwhile, we need to protect the local wildlife from further harm.\n\nCan you gather some materials for me? I'll need life in all its incarnations. Talk to Onu here in the grove to acquire a Seed of the Earth. Capture a Darkshore Wisp floating amongst the trees and we'll have a Seed of the Sky. Find a Seed of the Sea within seashells along the coast, west of here.", objectives = "" }
WordHunterWoW_QuestEN[13883] = { title = "Lousy Pieces of Ship", description = "Shoddy workmanship! There's no other explanation...\n\nThese ships must've been constructed in a hurry. Entire pieces of armor plating are falling off without even sustaining a direct hit!\n\nI'll show them how it is to be done. But first, I need you to recover the pieces from the sea floor.\n\nReturn to me with the pieces and I'll do the rest.", objectives = "" }
WordHunterWoW_QuestEN[13884] = { title = "Put Out The Fire", description = "Lord Magmathar's minions must first be dealt with if we're to retake this area and put a stop to the fiery destruction of the forest.\n\nThe lava ragers on the flow to the north are strengthened by being on their own element. I fear that on your own, you won't have much chance against them.\n\nWhen you are ready, speak to me again, and I will summon one of my own to assist you.", objectives = "" }
WordHunterWoW_QuestEN[13885] = { title = "In Defense of Darkshore", description = "Now that we know our preventative measures work, we should cover as much ground as possible.\n\nI've arranged to commandeer one of our hippogryphs, but I can't do this alone. Talk to my friend Orseus, next to the flight master right outside the grove here. Let him know when you're ready and I'll meet you there. We'll canvas Darkshore from the air and protect as many animals as we can!", objectives = "" }
WordHunterWoW_QuestEN[13886] = { title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", objectives = "" }
WordHunterWoW_QuestEN[13887] = { title = "Venomhide Eggs", description = "Now that you've built up an immunity to venomhide toxin, you can safely handle the animals and their eggs. Venomhides are vicious and must be trained from the moment they hatch.\n\nIf you want to ride one, you'll need an unhatched egg. Scattered throughout the Marshlands are a number of ravasaur nests. Look for the eggs with lighter colored shells -- those are the ones that will hatch venomhides.\n\nIf you bring me several of the eggs, I'll allow you to keep one and raise its hatchling, with my guidance.", objectives = "" }
WordHunterWoW_QuestEN[13888] = { title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", objectives = "" }
WordHunterWoW_QuestEN[13889] = { title = "Hungry, Hungry Hatchling", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe drawings are rough, but you can make out the shapes of diemetradons, stegodons, and pterrordaxes. As the raptor finishes the sketch, it looks up at you, bares its teeth, and makes a biting motion.\n\nYour venomhide hatchling must be craving fresh meat from these animals. Find and kill any type of diematradon, stegodon, or pterrordax in Un'Goro Crater and feed its meat to your hungry hatchling.", objectives = "" }
WordHunterWoW_QuestEN[13890] = { title = "Keep the Fires Burning", description = "This is no small task, {race}!\n\nWe have more ships arriving, and without the lighthouse they'll be lost - or worse! You are hereby charged with keeping its fire lit.\n\nCollect the blubber from the hydras in these waters, then bring it to the forge here to melt it into oil.\n\nThrowing that oil on the lighthouse fire will buy us the time we need.", objectives = "" }
WordHunterWoW_QuestEN[13891] = { title = "The Devourer of Darkshore", description = "Now that the creatures of Darkshore are safe, let's turn our attention to the artifact you found in the lake. I believe it's the work of a minion of the Old Gods. We'll fight these fiends using the very lifegiving energies of Darkshore itself! Take the Lifebringer Sapling to the shore of the shallow lake to the south of here. Wave it over the waters of the lake and it should disable that ancient artifact.\n\nBe careful, {name}. The artifact is likely to be guarded by who-knows-what.", objectives = "" }
WordHunterWoW_QuestEN[13892] = { title = "Leave No Tracks", description = "To the southwest lies the corpse of a being somehow related to the Old Gods that the Twilight's Hammer cultists worship.\n\nHe was defeated before our time -- if not by the Titans themselves, certainly by one of their creations.\n\nWe've noted an increase in cult activity in that area which can only mean something terrible is amiss.\n\nWe're going to need to find out what they're planning to do there and why.  Take this figurine, it'll help you avoid being detected while you gather intelligence.", objectives = "" }
WordHunterWoW_QuestEN[13893] = { title = "Soggoth and Kronn", description = "The Master's Glaive was the site of an ancient battle, {name}.  The titans sent twenty of their stone giants against Soggoth.\n\nOf those twenty giants, one survived.\n\nThe tablets say that Kronn, the largest of the stone giants allowed himself to be entangled by Soggoth's tendrils -- just long enough to be lifted close enough to the creature's skull... within reach of his mighty sword.\n\nIt's a good thing he's dead... we don't really have twenty stone giants lying around to stop him again.  ", objectives = "" }
WordHunterWoW_QuestEN[13895] = { title = "The Slumbering Ancients", description = "We may not have twenty stone giants to take on our enemy, but we giants of ancient lumber are as strong as any rock.\n\nLook around you, {race}.  My kindred sleep... yet they will heed the keeper's horn when the time of need is upon them.\n\nYou will find Aros, the keeper of the grove, beyond the bridge northeast of here.\n\nTell him the urgency of our situation.", objectives = "" }
WordHunterWoW_QuestEN[13896] = { title = "Unearthed Knowledge", description = "Listen, {name}.  We need to learn more about what we're up against.\n\nTo the southwest, beyond the Master's Glaive, there is a group of dwarven prospectors who were excavating the nearby ruins.\n\nPerhaps they have uncovered knowledge that is useful to us in this matter.", objectives = "" }
WordHunterWoW_QuestEN[13897] = { title = "The Battle for Darkshore", description = "The ancients of the grove have come to our aid, {name}.  I can see through their eyes even as we speak.\n\nThe Twilight's Hammer has been forced to hasten their ritual and have thus only managed to resurrect but a remnant of dread Soggoth.\n\nDestroy it before it's too late, {name}.  I am needed elsewhere.\n\nReturn to the druids at the Grove of the Ancients when it is all over they will direct you further.", objectives = "" }
WordHunterWoW_QuestEN[13898] = { title = "The Tides Turn Against Us", description = "We cannot let the naga get away with this, {name}.  Slaying the keeper of the grove amounts to a declaration of war.\n\nYou'll find their den inside a cave on the island of Naj'vel, far to the southwest.\n\nI want you to send them a clear message.", objectives = "" }
WordHunterWoW_QuestEN[13899] = { title = "The Darkscale Warlord", description = "If the naga want to throw in their lot with the Twilight's Hammer, then may Elune have mercy on them.\n\nGo into their lair in the island of Nazj'vel and find their leader, the naga warlord known only as Wrathspine.\n\nPerhaps the horn of the ancients can still be saved.", objectives = "" }
WordHunterWoW_QuestEN[13900] = { title = "The Offering to Azshara", description = "The warlord said the horn of the ancients was being offered to Azshara above Nazj'vel.\n\nPerhaps it's not too late to save the ancient relic from being destroyed.", objectives = "" }
WordHunterWoW_QuestEN[13901] = { title = "Deep Despair", description = "There is more to this naga problem than meets the eye, {class}.  It appears that the issue will not be resolved by merely thinning their numbers. To humble them, a more severe impression must be made.\n\nTravel to the northern end of Zoram Strand and enter Blackfathom Deep. Once there, demonstrate to the naga that their presence in this region will no longer be tolerated!", objectives = "" }
WordHunterWoW_QuestEN[13902] = { title = "Mounting the Offensive", description = "Our work in Darkshore is not yet done.  We might have stopped the landmass from shattering, but our enemies still have a strong presence in the area.\n\nI want you to contact a group of druids at the Grove of the Ancients, far to the south.  They are led by an old friend of mine, Balren of the Claw.\n\nTell them that the time has come to take the battle to our foes.  I will come to aid them as soon as we stabilize the area.", objectives = "" }
WordHunterWoW_QuestEN[13903] = { title = "Gorishi Grub", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.\n\nIt must want you to go to the Slithering Scar, in the center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.", objectives = "" }
WordHunterWoW_QuestEN[13904] = { title = "Poached, Scrambled, Or Raw?", description = "The venomhide hatchling's stomach growls as it gestures to get your attention. It begins scratching pictures of silithids into the dirt, adding small ovals underneath them. It looks at you hopefully and gestures at the circles.\n\nThey can only mean silithid eggs. The Noxious Lair, in western Tanaris and near the border with Un'Goro Crater, would probably be a great place to find the eggs your little hatchling wants.", objectives = "" }
WordHunterWoW_QuestEN[13905] = { title = "Searing Roc Feathers", description = "The hatchling looks at you for a moment, almost as if wondering whether you'll understand. It scrawls a picture of a pair of feathers in the dirt, then points with one claw to the bindings at its elbows and knees.\n\nIt doesn't seem hungry, but what could the feathers be for?\n\nIt must want them for adornments like the ones you've seen on other raptors. The largest feathers come from the searing rocs that congregate around the bones of large creatures in western Tanaris, northeast of Thistleshrub Valley.", objectives = "" }
WordHunterWoW_QuestEN[13906] = { title = "They Grow Up So Fast", description = "With your expert feeding and care, your venomhide hatchling will grow quickly. As they grow, their hatchling teeth will be replaced by adult teeth. If you keep the teeth shed by your hatchling as it grows, you'll have an easy way to tell when it's mature enough to be trained as a mount.\n\nYour venomhide will let you know what it needs, so pay close attention. When it has shed all of its baby teeth, return to me with your venomhide and the materials for your saddle and I'll do the rest.", objectives = "" }
WordHunterWoW_QuestEN[13907] = { title = "Sweeping Clean the Ruins", description = "The big beards at Ironforge sent me here to check on Remtravel's dig the moment they got word of the disaster. Look at it! Precious artifacts washed to sea, months of tedious digging undone in a moment.\n\nWhen the tidal waves hit, they demolished the murloc encampments along the shore. Good news? Naw, not with my luck. The survivors are squatting in the shelter of the ruins, and they're doing more damage than the elements ever could. Would you mind getting your waders on and taking care of things?", objectives = "" }
WordHunterWoW_QuestEN[13909] = { title = "Got Some Flotsam?", description = "We can figure this out, {name}. We just need some Dwarven ingenuity. Think, Groffy, think!\n\nThese murlocs are just looking for a home, right? Let's do something constructive. I mean that literally.\n\nAll sorts of debris was washed ashore during the catastrophe, and some of the decimated murloc hovels may still be salvageable. Run along the shore here and gather up any building materials fit for a murloc. That's an admittedly low standard. ", objectives = "" }
WordHunterWoW_QuestEN[13910] = { title = "A New Home", description = "Can we build it? Yes we can! Just west of the dig site I planted a banner on the shore. The sand is firm and it's as good a site as any. Take my tools and the parts you collected and build these ornery pests a different place to live.", objectives = "" }
WordHunterWoW_QuestEN[13911] = { title = "The Absent-Minded Prospector", description = "Who are you again? {name}? Have we met? If you're here from the League, you can tell them I'm not leaving! Not without my find. I had it, right in my hands! Then the screaming. Then the wetness.\n\nListen here whos-yer-name, I documented the whole thing in my journal the day the tidal wave hit. And I know just where I left it! The journal. Not the find. Help me get the one so we can get the other! Or vice-versa! Do you follow? Follow me!", objectives = "" }
WordHunterWoW_QuestEN[13912] = { title = "Swamped Secrets", description = "Underneath Remtravel's forgetful exterior is the mind of a genius, an enigma cloaked in senility. But I'm not about to give up on the old man. Look at what I found in his notes... not there... no, that's a shopping list... Here, on the page where he's trying to figure out what year it is: The Disc!\n\nWe think this Titan artifact is some sort of encrypted storage wheel. We were carefully unearthing it when the disaster hit, but hopefully it's still in the ruins. Dive in and grab it for me! ", objectives = "" }
WordHunterWoW_QuestEN[13913] = { title = "They Took Our Gnomes", description = "The gnome explosives squad we requested from Tinker Town arrived last week. Just in time to face an assault by the Horde. We lost a lot of soldiers that day. Most of the gnome team was taken as well. Now we're neck deep in Horde, Silverwind Refuge has been lost and we're down a dozen gnomes.\n\nI'm begging for your help here, {name}. Travel east to Silverwind Refuge and look for any gnome survivors. They were all carted off by a big, merciless orc named Thundrak. Find him and you'll find our gnomes.", objectives = "" }
WordHunterWoW_QuestEN[13918] = { title = "The Titans' Terminal", description = "Now that we have the disc, a lot of our earlier finds are starting to make sense. Shortly after my arrival, Prospector Remtravel unearthed what he presumed to be a prehistoric toaster.\n\nIt's my belief that this slotted box is some sort of data reader. Unfortunately, it broke apart and washed away with the rest of our base camp when the tidal wave struck!\n\nIt can't have gone far, {name}. Pieces must be buried in the nearby sand. Here, use my trusty buried artifact detector to comb the beach for them.", objectives = "" }
WordHunterWoW_QuestEN[13919] = { title = "A Trip to the Moonwell", description = "It didn't work.\n\n<A sorrowful and resigned expression upon his face, Pelturas removes the tear from the soup and gently washes it.>\n\nThe eruption of Thunder Peak must have affected it in some way. You must take the tear to the Moonwell of Purity, which still lies intact, protected by the goddess' power, at the southeast base of the volcano.\n\nThere, you will wash it in the sacred waters of Elune. What happens beyond that, I cannot say. I fear for my daughter's life. It is in your hands now, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13920] = { title = "Before You Go...", description = "We have urgent need for good {class}s at Hellscream's Watch, {name}. But before you're dispatched, there remains something that needs doing here.\n\nMost of our perishable goods were lost at sea due mainly to Alliance attacks. We must stock enough food to carry out our Ashenvale campaign.\n\nJust east of here, you should find wildlife in abundance. Bring back the best meat you can find for our troops!", objectives = "" }
WordHunterWoW_QuestEN[13921] = { title = "He Who Would Be Forgiven", description = "<A voice from inside the moonwell flows over your mind, bringing you a perfect sense of peace.>\n\nYou seek to cure a child, but know that all things come at a cost. To the east lies Raynewood Tower. Standing outside the tower, next to my moonwell, is one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption, {name}. Will you help him to attain that which he desires and in so doing achieve your own goal?", objectives = "" }
WordHunterWoW_QuestEN[13922] = { title = "In the Hands of the Perverse", description = "My former clan, the Felmusk of Night Run, raided Fallen Sky Lake some time ago, stealing the moonstones that were unique to the area.\n\nThose moonstones are known to have great healing properties and surely can be used to cure the little girl that lies sick in Astranaar.\n\nNight Run rests up the road to the east that runs north. There are multiple paths that lead up into the hills on its eastern side, and it is there that you will find my unrepentant brethren. They will have what you seek.", objectives = "" }
WordHunterWoW_QuestEN[13923] = { title = "To Hellscream's Watch", description = "Into the fray with you, {race}!\n\nHellscream's Watch is one of our most contentious fronts in Ashenvale. The experience should serve you well... assuming you survive.\n\nWhen you've made ready, speak with Andruk. I've arranged for him to transport you directly to your station.\n\nOnce you've arrived, seek out Captain Goggath. He will guide you further.\n\nBring pain and death to our enemies! For the Horde!", objectives = "" }
WordHunterWoW_QuestEN[13924] = { title = "All's Well", description = "Thank you for saving me from a fate worse than death, {name}! For saving both the child and myself!\n\nWell, the child is almost saved. All you have to do is take the moonstones back west down the road to Astranaar. Hand them to Pelturas and he will know what to do.\n\nGo in peace, my friend. Elune be praised!", objectives = "" }
WordHunterWoW_QuestEN[13925] = { title = "An Ounce of Prevention", description = "Are you familiar with the Old Ones, {name}? Onu and I agree that the artifact you found in the lake can only be their work, and it's devouring Darkshore. Something is stirring up terrors we thought dead long ago. This is bigger than you or me, but my first concern is protecting the wildlife.\n\nHere, this sapling contains the life essence you gathered for me. I believe it can protect the local fauna. Test it out on a nearby un-consumed bear, stag, or moonstalker, and let me know what happens!", objectives = "" }
WordHunterWoW_QuestEN[13926] = { title = "Little Orphan Roo Of The Oracles", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", objectives = "" }
WordHunterWoW_QuestEN[13927] = { title = "Little Orphan Kekek Of The Wolvar", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", objectives = "" }
WordHunterWoW_QuestEN[13928] = { title = "Recover the Fallen", description = "I and my sentinels have been ordered by Keeper Ordanus to stay here and hold the tower. So far we've been able to repel the Horde, but now they're going around us to directly attack the retreat to the north.\n\nThe keeper sent out his dryads to defend the tree, but they do not seem to be much of a match for the vanguard of the Warsong orcs.\n\nI need you to go out there and recover as many laughing sister corpses as you can. Take them to Halannia inside the tree at the retreat. She will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[13929] = { title = "The Biggest Tree Ever!", description = "Before there was a big war and we left the village, we remember Soo-say telling us all about the biggest tree ever!\n\nSoo-say call it Grizzlemaw or something. Soo-say tell us it in the middle Grizzle Hills. No, wait, that not what Soo-say say. Soo-say say Grizzly Hills. Now we remember! Tree is big and right in middle of Grizzly Hills. Can't miss!\n\nYou take us there, oki? We see inside of giant tree? Soo-say tell us big bear men live in tree too. Maybe we see them.", objectives = "" }
WordHunterWoW_QuestEN[13930] = { title = "Home Of The Bear-Men", description = "High Shaman Rakjak always tell stories of mighty warriors, even ones far away. Sometimes he tell stories about giant bear-men fighting great battle for tree-city.\n\nMaybe you take Kekek there, see tree, see battle! High Shaman Rakjak tell Kekek that giant tree-city Grizzlemaw stand in the middle of Grizzly Hills.\n\nKekek never see a city before meeting orphan lady, but this city have no warriors, only men in purple dresses. Kekek want to see real warriors fight for real city.", objectives = "" }
WordHunterWoW_QuestEN[13931] = { title = "Another Year, Another Souvenir.", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "" }
WordHunterWoW_QuestEN[13932] = { title = "Another Year, Another Souvenir.", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "" }
WordHunterWoW_QuestEN[13933] = { title = "The Bronze Dragonshrine", description = "Sometimes High-Oracle Soo-say tell stories about a shrine to dragon-things, not like great rain stone, but different. Soo-say tell us maybe we see ourselves there, but not like in a shiny. Soo-say mean we could see what we are like many years from now.\n\nYou take us there? We remember shrine to bronze dragon-things in place called Dragonblight. Soo-say say great rain stone show him shrine to northeast of Wyrmrest Temple, or northwest of place dryskins call Wintergarde Keep. We go?", objectives = "" }
WordHunterWoW_QuestEN[13934] = { title = "The Bronze Dragonshrine", description = "When Kekek was a pup, he sometimes heard elders talking about a far-off shrine. Sometimes they say that bronze dragon-things there know all about future.\n\nKekek tell you he be great warrior, now we go see. Bronze dragon-thing shrine somewhere in Dragonblight, northeast of dragon-thing temple called Wyrmrest, also northwest of man-town called Wintergarde.\n\nWe go there, see future. Prove orphan-lady wrong about Kekek. Kekek warrior, not bully.", objectives = "" }
WordHunterWoW_QuestEN[13935] = { title = "Defend the Tree!", description = "We have been using the power of the Forest Heart to defend the tree from the Horde, but its power is not without limit. We must use it to take the fight to them!\n\nShadumbra, the great cat of the forest, prowls nearby. It is from her that we shall draw our inspiration. You will become one with the shade of Shadumbra. You will take the essence of the panther into you and lay waste to those who dare attack the might of Ashenvale!", objectives = "" }
WordHunterWoW_QuestEN[13936] = { title = "Tweedle's Dumb", description = "Delays, delays, delays! I'm at wit's end!\n\nI was told that this goblin was brilliant - that he'd come up with gadgets sure to shock the enemy into submission. So far he's produced nothing but empty promises. If he comes up empty-handed again, I'm going to toss him off the cliff!\n\nYou go and speak to him, {class}. Let him know that my fuse is running short!", objectives = "" }
WordHunterWoW_QuestEN[13937] = { title = "A Trip To The Wonderworks", description = "We have time for one more stop? We heard Dalaran has toy store, but we never get to go there. Orphan mistress says too many orphans would crowd the store. Maybe we can go, just us?\n\nWe can have a small paper zeppelin? We think they have those at Wonderworks in Dalaran. We always wanted to play with one. Maybe you throw one to us?", objectives = "" }
WordHunterWoW_QuestEN[13938] = { title = "A Visit To The Wonderworks", description = "You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek?\n\nKekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?", objectives = "" }
WordHunterWoW_QuestEN[13940] = { title = "Leaving the Dream", description = "Hold on tight, {name}.  The journey back to the waking world can be a little rough on unprepared minds and bodies.", objectives = "" }
WordHunterWoW_QuestEN[13942] = { title = "Set Us Up the Bomb", description = "I'm definitely on to something here!\n\nI have enough volatile elements salvaged from our arsenal to make the explosives Goggath wants, but I need to stabilize it and pack it into bombs.\n\nWhat I need is some clay - and not just any clay... moon-kissed clay.\n\nIt's only found on the northern banks of Astranaar Lake, and it possesses the qualities I need to bring out the full potential of my discovery!", objectives = "" }
WordHunterWoW_QuestEN[13943] = { title = "Breathing Room", description = "Our forces are not ready to assault Astranaar just yet, {class}. They know we're coming, though, and they're not content to sit and wait for us. At the base of this cliff they've created a camp from which they launch bothersome attacks by the light of the moon.\n\nBefore these skirmishes bolster their confidence any further, I want you to visit them with the wrath of the Horde! Return to me when the elves have been humbled a bit.", objectives = "" }
WordHunterWoW_QuestEN[13944] = { title = "Small Stature, Short Fuse", description = "<Tweedle gesticulates emphatically.>\n\nI've done it! This should satisfy even Goggath!\n\nWe just need a test that will sufficiently show off our efforts... ahh, the wagon!\n\nThe bossman's wanted that rotted out piece of junk hauled off for days. Use my explosives to get rid of it, then see what the captain has to say!", objectives = "" }
WordHunterWoW_QuestEN[13945] = { title = "Resident Danger", description = "The Gnarlpine aggression is limiting our options. None of our kind are eager to bring blade and arrow against creatures that were once our friends, but I grow fearful that they are going to set their sights on Dolanaar soon.\n\nThe biggest concern to me are the furbolg in Ban'ethil Hollow and Ban'ethil Barrow Dens. I need you to travel to the west, make your way into the Barrow Den, and kill as many of the Gnarlpine as you can. We probably won't have many more chances to limit their strength - be swift.", objectives = "" }
WordHunterWoW_QuestEN[13946] = { title = "Nature's Reprisal", description = "I'm glad you were willing to atone for your mistake - it speaks a great deal about your character.\n\nI have another task for you. I have gathered some ireroot seeds. They are somewhat like fel cones, but quite a bit more potent. Nature often responds very negatively to demons, and these ireroot seeds prompt a very concentrated form of that reprisal.\n\nTo our north, in Fel Rock, there are grellkin that are far beyond redemption. Use the ireroot seeds to route them before they become a more serious threat.", objectives = "" }
WordHunterWoW_QuestEN[13947] = { title = "Blastranaar!", description = "So, Tweedle finally came through on those explosives, eh?\n\nThey couldn't have come at a better time. The elves of Astranaar are preparing to make a devastating assault on our camp as we speak.\n\nDrop our new weapon on them from the skies! The destruction of Astranaar will be a dagger in the heart of night elves everywhere!\n\nSpeak with Thraka when you're ready to begin the assault.\n\nAim true, {class}.", objectives = "" }
WordHunterWoW_QuestEN[13948] = { title = "Stepping Up Surveillance", description = "The cultists appear to be digging out the remains of a being known as Soggoth the Slitherer.\n\nPerhaps their superiors on the rafters above have more information.", objectives = "" }
WordHunterWoW_QuestEN[13949] = { title = "Crossroads Caravan Pickup", description = "<Halga grins disarmingly, holding up an enormous firearm.>\n\nHave you ever used one of these, {name}? It's a beast. Hell with a handgrip. Too heavy to use on foot, but perfect when riding at the head of a caravan. I call it my 'street sweeper.'\n\nWe need to get those supplies you've collected to the Crossroads, and I expect trouble. I'd like for you to ride shotgun. Literally! Say the word when you're ready and I'll put you at the head of our next caravan.", objectives = "" }
WordHunterWoW_QuestEN[13950] = { title = "Playmates!", description = "Orphanage gets real lonely, you know? Sometimes we want to go places, meet new friends.\n\nMaybe you can take us somewheres with other hatchlings? We heard about a place called Winterfin Retreat, in the big Borean Tundra. We think it's way in the northwest, near the edge of the Coldarra-island.\n\nThe orphan lady say someone brave save a bunch of hatchlings there. We think they lonely, too. We think they need friends. You take us there?", objectives = "" }
WordHunterWoW_QuestEN[13951] = { title = "Playmates!", description = "Kekek think there not enough other pups living with orphan-lady. Maybe we go visit some others?\n\nKekek know a tribe that lives in Dragonblight, at place called Snowfall Glade. You know? Snowfall Glade north of walrus-men town of Mo'aki Harbor and south of Ruby Dragonshrine.\n\n<Kekek scowls at the mention of the tuskarr.>\n\nYou take Kekek there, to some of the villages there. Maybe we meet new wolvar, show them how fierce Frenzyheart are!", objectives = "" }
WordHunterWoW_QuestEN[13952] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "" }
WordHunterWoW_QuestEN[13953] = { title = "Naga In Our Midst", description = "The creature appears to have had its skull broken in a fight with Aros.  It looks like what you've heard described as a naga before.\n\nIt is said that despite their monstrous features, naga are night elves warped by the arcane magic of Queen Azshara.\n\nIt seems they've decided to stop you from obtaining the horn of the ancients.", objectives = "" }
WordHunterWoW_QuestEN[13954] = { title = "The Dragon Queen", description = "One of High-Oracle Soo-say's stories says Great Ones made all the dragons and a queen for the dragons, too. We want to see her! Would you take us to the top of Wyrmrest Temple? We remember Soo-say telling us the temple-thing was in the middle of Dragonblight.\n\nWe really want to meet dragon queen. She must be so big and pretty. Maybe she help us find new parents.\n\nYou take us?", objectives = "" }
WordHunterWoW_QuestEN[13955] = { title = "The Dragon Queen", description = "Kekek always liked dragons. Always wanted to be one, but orphan-lady said no. But she did say maybe you take Kekek to meet dragon queen.\n\nKekek think orphan-lady have good idea for once. You take Kekek to Wyrmrest Temple in the middle of Dragonblight? Fly all the way to top to meet dragon queen. She must be really big, to be queen of all dragons. Kekek can't wait to see!", objectives = "" }
WordHunterWoW_QuestEN[13956] = { title = "Meeting a Great One", description = "High-Oracle Soo-say always tell us about how Great Ones built shrines and we give them shinies, but he never see Great Ones. No one see Great Ones, but maybe you know how to find one?\n\nSoo-say told us the Great Ones made a waygate and put it in the center of the southern part of Sholazar. Soo-say not say where it goes, but maybe it take us to a Great One! Take us through that waygate and let's find out, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13957] = { title = "The Mighty Hemet Nesingwary", description = "Know who Kekek always wanted to meet? Hemet Nesingwary.\n\nMaybe you take Kekek to see him? Elder Harkek tell us all about him. He come to Sholazar to hunt biggest creatures anywhere! Even Frenzyheart elders respect Hemet Nesingwary as great hunter.\n\nElder Harkek tell Kekek that Nesingwary Base Camp in the middle of west side of Sholazar, right on river called Seabreach Flow. We go visit and learn how to hunt like Hemet?", objectives = "" }
WordHunterWoW_QuestEN[13958] = { title = "Condition Critical!", description = "We have the enemy on their heels. Victory is within sight!\n\nIt is not yet time to celebrate though, {class}. There remains much to be done before the Horde can lay claim to Ashenvale.\n\nAt Raynewood Retreat to the east a battle has been joined. Reports indicate many Horde wounded.\n\nTake these medical supplies there and give them to Thagg. Tell him of our assault on Astranaar. It may help to bolster morale.", objectives = "" }
WordHunterWoW_QuestEN[13959] = { title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our daddy now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki? ", objectives = "" }
WordHunterWoW_QuestEN[13960] = { title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.", objectives = "" }
WordHunterWoW_QuestEN[13961] = { title = "Drag it Out of Them", description = "It is our instinct to simply lash out at our attackers, but wisdom dictates another path. We should interrogate one of these quilboar invaders and learn all we can. Take this net, {name}, and ensnare a quilboar pillager attacking our farm just west of here. Club the beast unconscious and bring him to me.", objectives = "" }
WordHunterWoW_QuestEN[13962] = { title = "Stalemate", description = "The triage kits will help us keep up the fight, but we are at a stalemate.\n\nThe dryads die easy enough, but their leader is resurrecting them soon after they fall. We face an endless stream of the vermin!\n\nKeeper Ordanus hides in that mutated tree. Our efforts to fight our way to him have been in vain. Perhaps you could work your way to him while we contend with his dryads...\n\nSurely, this is child's play for someone who has conquered Astranaar. No?", objectives = "" }
WordHunterWoW_QuestEN[13963] = { title = "By Hook Or By Crook", description = "I suppose he'll come around with some cold water to the face. What do you think he'll tell us?\n\nI'll secure him inside our livestock pen behind me here. I don't think he'll stay conscious long. Find out what you can about why the quilboar are attacking our farms! I'll leave the interrogation methods up to your better judgment.", objectives = "" }
WordHunterWoW_QuestEN[13964] = { title = "To the Spire", description = "We've lost Silverwind Refuge! All that I know is that there was a surprise attack by the Horde and that they somehow turned Mystral Lake's elemental guardians against us.\n\nThe survivors have fallen back to Stardust Spire. {name}, they need your help.\n\nHead south by southeast. You'll find the spire at the mouth of the Talondeep Pass, which leads into the Stonetalon Mountains. I'm sure that you'll find Sentinel Velene Starstrike helping with the counter-offensive there.", objectives = "" }
WordHunterWoW_QuestEN[13965] = { title = "Check in on the Edunes", description = "{name}, if you have a moment to spare, I would enlist your aid in a simple matter.\n\nI have not heard from my friends, the Edunes, in some time. I was wondering if you could swing west and check in on them?\n\nYou have my thanks. Their cottage sits on a small plot of land just to the west of the Shrine of Aessina.", objectives = "" }
WordHunterWoW_QuestEN[13966] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[13967] = { title = "Thinning the... Herd?", description = "The furbolg are more numerous than we expected in these southern regions. They have also been far more aggressive here than we would like.\n\nWith our resources divided between hunting down elves and harvesting much-needed lumber, that leaves you to help me put an end to our furbolg distraction.\n\nI have research to conduct here. In the meantime, I need you to take a more hands-on approach. Bring me the ears of nearby furbolg as proof to Tarkan that the problem is being dealt with.", objectives = "" }
WordHunterWoW_QuestEN[13968] = { title = "The Tortusk Takedown", description = "In the wake of the chaos down south, this \"Tortusk\" brute seems to have rallied all of the Razormane refugees to his banner. Under his leadership, he's turned them into little more than brigands. There's no negotiating with his type; Tortusk must be destroyed.\n\nIf our prisoner is to be believed, you'll find Tortusk southeast of here at a place called Thorn Hill. Search the bluffs where he has a commanding view of the road. Kill him, {name}, and the immediate threat should cease.", objectives = "" }
WordHunterWoW_QuestEN[13969] = { title = "Grol'dom's Missing Kodo", description = "Friend, if you are traveling south to Thorn Hill, I was wondering if you could locate one of our missing kodos? Not every caravan has made it up the pass from Far Watch Post. Those Razormane brutes hijacked a pack animal yesterday morning. It may not still be alive, but if it is, we cannot afford to lose more of our livestock.", objectives = "" }
WordHunterWoW_QuestEN[13970] = { title = "Animal Services", description = "Kodos are resilient creatures. With some food, the big guy may come around.\n\nThe Razormane have stolen plenty of grain from previous caravans. You can gather up stolen grain from the nearby camps.", objectives = "" }
WordHunterWoW_QuestEN[13971] = { title = "The Kodo's Return", description = "The great beast rises slowly to its feet, the loose Barrens soil spilling from its revitalized limbs. Instinctively it trudges back toward its home at Grol'dom Farm.\n\nYou'll want to check in with Kranal Fiss to make sure the kodo made it. ", objectives = "" }
WordHunterWoW_QuestEN[13973] = { title = "The Grol'dom Militia", description = "They came out of nowhere, {class}! Quilboar from horizon to horizon. Spines and snouts and teeth. We fell back to the farm but they kept on coming.\n\nOur best defenders have fallen in the field, and we've no sign of Farmer Ralton. I need you to go on the offensive for me! Hold these swine at bay while I defend the wounded until help arrives. ", objectives = "" }
WordHunterWoW_QuestEN[13974] = { title = "Tweedle's Tiny Parcel", description = "Wahoo!!\n\nLook at 'em burn! It's revolutionary! A real breakthrough in explosive technology - which, of course, is the only kind that matters....\n\nI'm gunna be the envy of every goblin south of Northrend!\n\nBelieve it or not, I've actually refined the formula to be even more potent!\n\nHere. Take a sample of this stuff southeast to Silverwind Refuge. Maybe my cousin Flooz can use it to help the Horde capture that objective.", objectives = "" }
WordHunterWoW_QuestEN[13975] = { title = "Crossroads Caravan Delivery", description = "<Rocco hands you a familiar-looking shotgun.>\n\nI took the liberty of cleaning up Halga's artillery for you. I'm sure I don't need to warn you about the kickback. Just ask me when you're ready to mount up for the Crossroads! Thork is waiting for you there. Be sure not to give him any lip.\n\nDon't stop for nothing, {name}, and if someone gets too close, just give 'em a thump with the butt-end of your gun. Do us proud!", objectives = "" }
WordHunterWoW_QuestEN[13976] = { title = "Three Friends of the Forest", description = "Care to make a quick trip to the south? I've three friends that I haven't heard from in a while. With these strange tentacles popping out of the ground to the north, and all of the demonic activity, I don't dare leave my family.\n\nBolyun set up his camp in the southwest corner of the forest, just to the northwest of that damnable Fire Scar Shrine. Alenndaar and Harlown joined him, so they should all be okay, but you never know.\n\nThanks, {name}.", objectives = "" }
WordHunterWoW_QuestEN[13977] = { title = "Mass Production", description = "Wahoo!! Did you SEE that?!\n\nWe need to get this into production right away!\n\nHere. Take the rest of the stuff to Jinx. You'll find him setting up our new facility just west of here.\n", objectives = "" }
WordHunterWoW_QuestEN[13979] = { title = "The Goblin Braintrust", description = "If we could just stop the damned bombing from the goblins' creations we'd be able to launch a counter-offensive to take back Silverwind Refuge!\n\nIt's been my experience that goblins are either lazy and unproductive, or too productive and end up killing themselves with their own explosives. Unfortunately for us, they're being motivated by the brilliant Chief Bombgineer Sploder.\n\nGet up to the Skunkworks on the west side of the refuge and don't come back until you have the Chief Bombgineer's head!", objectives = "" }
WordHunterWoW_QuestEN[13980] = { title = "They're Out There!", description = "They're out there, {class}. And they're on to us.\n\nSome of my men have begun turning up dead. Elf attacks, no question about it.\n\nMy guess is that your work at Astranaar has them desperate to stop our progress here. A last ditch effort to escape defeat!\n\nTake these goggles. They'll help you see even the sneakiest of the elves. Keep them off my back while we finish weaponizing your explosives.", objectives = "" }
WordHunterWoW_QuestEN[13981] = { title = "They Set Them Up The Bomb!", description = "This is clearly the biggest explosive that you've ever laid eyes upon. What in the world could the goblins be thinking about bombing with such a monstrosity?\n\nTo your eye the thing looks like it's almost complete. The goblins appear to have built it well -- it looks as if it's impervious to any damage that you could do to it, and certainly too big for you to carry out of here.\n\nYou'd better report The Bomb to Huntress Jalin at Stardust Spire to the southwest!", objectives = "" }
WordHunterWoW_QuestEN[13982] = { title = "In a Bind", description = "{name}, you must be cautious. Kaliva is still about and when she captured us, she specifically mentioned your name.\n\nOnly her heart can free us from these chains, but I think it's all a trap for you!", objectives = "" }
WordHunterWoW_QuestEN[13983] = { title = "Building Your Own Coffin", description = "Once it's complete, we're going to need to get this bomb down to Saurboz.\n\nAnd by 'we', I mean 'you'.\n\nWith so many of the enemy prowling about, I'll need to create something special if you're to have any chance of success.\n\nI can modify one of these busted shredders, but I'll need a few parts. You should have no trouble finding them in the woods to the west.\n\nRound them up while I finish work on the bomb.", objectives = "" }
WordHunterWoW_QuestEN[13985] = { title = "Clear the Shrine", description = "An end must be put to the Burning Legion's evil!\n\n{name}, you have defeated one of their most powerful, but there are still multitudes of demons infesting the woods to the east in Fire Scar Shrine.\n\nAs a friend of the forest, will you slay these foul creatures and then warn Big Baobob, the great ancient of war at the Shrine of Aessina to the northeast?", objectives = "" }
WordHunterWoW_QuestEN[13987] = { title = "The Last Stand", description = "{name}, I desperately need your help! I cannot hold out forever against this demonic onslaught. If I fall, Astranaar is next!\n\nPlease help me!", objectives = "" }
WordHunterWoW_QuestEN[13988] = { title = "A Growing Problem", description = "An explosion of life from barren soil... My companion Jerrik has described similar events happening elsewhere in the Barrens. I shall have to see this for myself, but I cannot abandon my post.\n\nHere, {name}, I will loan you my 'eyes.' My eagle companion here has served me since I was named. Please accompany him to Thunderhead Summit, where Jerrik awaits, and we will investigate.\n\nTo get to the peak, follow the road east out of the Crossroads. Turn south when you reach a large stone scrawled with paintings.", objectives = "" }
WordHunterWoW_QuestEN[13989] = { title = "King of the Foulweald", description = "I care little for who you are, {race}. What I do care about is the salvation of the furbolg.\n\nTake this Bloodtooth tribe banner a short ways northeast into Greenpaw Village and place it upon their totem mound. They will consider this an act of aggression and try to destroy the banner. Hold your ground until their chief, Murgut, appears to save face for the tribe, then kill the traitor!\n\nGovern your strength wisely, friend, you're in for a long fight.", objectives = "" }
WordHunterWoW_QuestEN[13991] = { title = "The Purloined Payroll", description = "Well, {name}. I admit there's a place for you in my beloved Horde. You've shown me strength, cunning, initiative ... Even Thork recently mentioned you by name, and neither of us are easily impressed. Well done.\n\nNow it's time to start pulling your weight. This week's payroll for the Crossroads guards has gone missing. Gazrog in Ratchet is heading up the investigation. Talk to him!\n\nSimply follow the road East of here to the coast.", objectives = "" }
WordHunterWoW_QuestEN[13992] = { title = "A Little Diversion", description = "I was sent here to scout out the centaur activity. I've been trackin' their every movement for days! It's time for me ta sneak out, but they've got this oasis surrounded.\n\nYou look like a dangerous one. Can you make a lot of noise for me? Stir 'em up! Start killin' indiscriminately. While they're looking out for you I'll slip out to get my info to Regthar Deathgate.", objectives = "" }
WordHunterWoW_QuestEN[13995] = { title = "King of Centaur Mountain", description = "We were sent here to track movements of the Kolkar centaur, but after a week of watching these dirty animals scamper all around this oasis, I'm itching to give my axe a taste of their necks. What do you say, {class}? Want to cause a little havoc with me?\n\nLet's see if we can attract the attention of their strongest warrior, Kurak.", objectives = "" }
WordHunterWoW_QuestEN[13998] = { title = "In Fungus We Trust", description = "I've cultured these unusual spores you dug up with a most magnificent cocktail of ... reagents ... that I'm fond of. I'm eager to see how my manipulated spores react to the waters of the Crossroads oases.\n\nThe Stagnant Oasis to the southeast should provide us an uncontaminated site for our experiment. Simply plant this culture in the moist soil anywhere near the oasis, and document the results for me.\n\nBe sure to cover your mouth, {class}.\n\n<Helbrim grins disarmingly.>", objectives = "" }
WordHunterWoW_QuestEN[13999] = { title = "Who's Shroomin' Who?", description = "Think of the possibilities, {name}! Fast-growing fungal delivery agents for any manner of toxins. My companions in the Undercity will want to hear about this.\n\nHere are my notes and some additional samples. If we're fast, we can catch the next ship bound for the Eastern Kingdoms. Take the road east of here and follow it to the goblin town of Ratchet. Look for the Broken Keel tavern toward the south side of town and deliver these to my associate Sashya within.", objectives = "" }
WordHunterWoW_QuestEN[14001] = { title = "Goblin Escape Pods", description = "{name}, I'm sorry, I thought you were dead!\n\nThis is just crazy. We sailed into a fight between the Alliance and Horde!\n\nYou know, our brothers and sisters still need to be rescued.\n\n<He points out all of the escape pods in the water around you.>\n\nI think I'm going to sit here a while longer and catch my breath. Can you swim around and let them out? Take my pair of thermohydratic flippers so you can get around faster.\n\nLet Sassy know that I'll swim in shortly.", objectives = "" }
WordHunterWoW_QuestEN[14003] = { title = "Samophlange Repair", description = "Well that didn't go as expected. I think I busted it.\n\nNo need to panic, though. Do me a favor and walk this across the way to Brak here in the camp. He'll bang this sucker back into shape real quick!", objectives = "" }
WordHunterWoW_QuestEN[14004] = { title = "Return to Samophlanger", description = "Well, that didn't work. The structural integrity of the samophlange is at an all-time low. I could add some more dials to try and fix it, but...that might make things even worse.\n\nLook what I discovered when I blocked the release valve and blew the cover off the differential casing, though: the personal stamp of \"Boss Copperplug.\"\n\nTake this back to Sputtervalve and tell him to find this Copperplug genius. When you're done here, just talk to me and I'll send you back using Brak's teleporter.", objectives = "" }
WordHunterWoW_QuestEN[14005] = { title = "The Vengeance of Elune", description = "As Teldrassil purges itself of the corruption that has perverted its growth for all of these years, a malevolent growth has formed near the tree's edge, south of here. We have an opportunity to strike out and purge the source of the fel moss that has tainted the gnarlpine, the timberlings, and everything else.\n\nWith the water that you've collected from the moonwells and the renewed strength of Teldrassil herself, I can grant you great power for a short while. Put an end to this corruption, {name}.", objectives = "" }
WordHunterWoW_QuestEN[14006] = { title = "Read the Manual", description = "Back when I was in the Tinker's Union, Boss Copperplug was the best engineer we had. He defected to the Venture Company shortly before I left, and took his greatest techniques with him. He hoarded his secrets, doling out bits and pieces of knowledge to his trusted inner circle.\n\nIf he built the samophlange, then he's probably got the manual. Last I heard, he was operating right here, out of Boulder Lode mine to the northeast. Get the manual from him, and collect the pages from his followers.", objectives = "" }
WordHunterWoW_QuestEN[14014] = { title = "Get Our Stuff Back!", description = "Our bombs and tools! Those sneaky monkeys to the east stole them all in the dead of night!\n\nCan you go out there and get them back for us, {name}? Without those tools, we have absolutely no way to get off of this island!", objectives = "" }
WordHunterWoW_QuestEN[14016] = { title = "The Black Knight's Curse", description = "I wanted to remove the Black Knight's remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen.\n\nWould you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what's happening? ", objectives = "" }
WordHunterWoW_QuestEN[14017] = { title = "The Black Knight's Fate", description = "You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker's Watch, the encampment on the rise west of the tournament grounds.\n\nWhatever the cultists are doing must be stopped. The rumors I've heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.", objectives = "" }
WordHunterWoW_QuestEN[14018] = { title = "He Who Would Be Forgiven", description = "The voice of the goddess spoke to you at the moonwell, {name}. The cure for Relara lies to the east at Raynewood Tower. The one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption. It is up to you to assist him and in so doing, hopefully help my child as well.", objectives = "" }
WordHunterWoW_QuestEN[14019] = { title = "Monkey Business", description = "We've got major problems with the monkeys in the jungle to the east. They've stolen all of our explosives, and now they're going around throwing them.\n\nSometimes at us!\n\nI had Fizz Lighter take some of his nitro and put it in these bananas. No monkey can resist a bunch of bananas!\n\nAll you have to do is go out there and feed them.", objectives = "" }
WordHunterWoW_QuestEN[14021] = { title = "Miner Troubles", description = "Smart mining monkeys!\n\nThey're all over the inside of the cavern, mining... with picks! It's just not natural and I'm sure it's because of the kaja'mite!\n\nNone of my miners have come back out. I don't have many left! You can see my predicament, {name}.\n\n<The foreman lowers his voice.>\n\nThese guys are nowhere near as good as my old group of jungle trolls. Ah, those were the days.\n\nMaybe you can escort my last miner here through the cavern and keep those monkeys off of him? We need that kaja'mite!", objectives = "" }
WordHunterWoW_QuestEN[14022] = { title = "Pilgrim's Bounty", description = "Won't you celebrate Pilgrim's Bounty with us, {name}? It's a time for reflecting on your journeys and your good fortune, sharing plentiful food and stories with friends.\n\nYou can partake of wonderful Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Gregory Tabor. You will find him just outside Stormwind's gates.", objectives = "" }
WordHunterWoW_QuestEN[14023] = { title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to Jasper Moore over near the tables.", objectives = "" }
WordHunterWoW_QuestEN[14024] = { title = "Pumpkin Pie", description = "That spice bread stuffing you made smells delicious, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He's bound to be running low by now.", objectives = "" }
WordHunterWoW_QuestEN[14028] = { title = "Cranberry Chutney", description = "If you haven't tried the cranberry chutney yet, you're in for a treat. It's made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I'd trade some for the pie you brought.", objectives = "" }
WordHunterWoW_QuestEN[14030] = { title = "They're Ravenous In Darnassus", description = "Thanks for bringing the cranberry chutney. There's so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don't suppose you'd be willing to step in and whip up some more spice bread stuffing and pumpkin pie? The vendor should have all the ingredients you need\n\nYou should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior's Terrace.", objectives = "" }
WordHunterWoW_QuestEN[14031] = { title = "Capturing the Unknown", description = "Heya, {name}, there are strange cave paintings and other artifacts all over the cavern.\n\nDo you think you could use your belt-mounted KTC Snapflash camera to capture images at the designated spots? Also, snap a pic of the altar in the back of the cavern.\n\nI'm sure that Sassy will want the intel.", objectives = "" }
WordHunterWoW_QuestEN[14033] = { title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Teldrassil sweet potatoes. They're used to make the most delicious candied sweet potatoes you've ever tasted.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They're one of his favorites, but to hear him tell it, everything's his favorite!", objectives = "" }
WordHunterWoW_QuestEN[14034] = { title = "Club Foote", description = "All this new friction between the Alliance and the Horde was leading to windfall profits, until Rear Admiral Hartley sailed into MY harbor and started poking his prow into my business. He's been searching and seizing vessels flying horde colors with the goal of depriving them use of a neutral port.\n\nI'm not about to allow some fat-fingered human to cut into my profits! Get me the schematics of his flagship. Hartley's Chief Engineer is soaking himself at the Broken Keel Tavern just up the hill...", objectives = "" }
WordHunterWoW_QuestEN[14035] = { title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a magnificent centerpiece, and I'm not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn't have a problem finding one.\n\nOnce you're done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?", objectives = "" }
WordHunterWoW_QuestEN[14036] = { title = "Pilgrim's Bounty", description = "Are you here to celebrate Pilgrim's Bounty with us? It was once a time for reflecting on your journeys and your good fortune while sharing a meal with friends. Many still mark the occasion.\n\nYou can partake of Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Miles Standish. You will find him in the courtyard above Undercity.", objectives = "" }
WordHunterWoW_QuestEN[14037] = { title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to William Mullins over near the tables.", objectives = "" }
WordHunterWoW_QuestEN[14038] = { title = "Love it or Limpet", description = "<Gazlowe spreads the plans on the table and jabs a tiny finger aft of the ship below the waterline.>\n\nThere! The hull is thinnest here, where the crankshaft meets the paddlewheel. And it's right next to the magazine!\n\n{name}, I can't be held responsible if some enterprising Horde {class} were to attach a limpet mine to that part of the hull. Not even if I supplied the mine. And paid him. Handsomely. The ship is anchored just southeast of here... go to it!\n\nThen radio me with this stolen gnomecorder.", objectives = "" }
WordHunterWoW_QuestEN[14039] = { title = "Home of the Kaldorei", description = "It has been an undeniable honor to have met you. You are a testament to the nobility of your race.\n\nGo now and finish this final task. Take the waters to Tyrande Whisperwind in Darnassus.", objectives = "" }
WordHunterWoW_QuestEN[14040] = { title = "Pumpkin Pie", description = "That spice bread stuffing you made is a hit, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He's bound to be running low by now.", objectives = "" }
WordHunterWoW_QuestEN[14041] = { title = "Cranberry Chutney", description = "Have you tried the cranberry chutney yet? It's made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff?", objectives = "" }
WordHunterWoW_QuestEN[14042] = { title = "Ammo Kerblammo", description = "Hartley must've unloaded all of his ordnance along the beach. Let's pull his teeth out, {name}!\n\nRun along the shore and look for his munitions stockpiles. Light 'em up and he'll be land-locked and unarmed while the Bellipotent is repaired.\n\nI'll meet you back here in Ratchet.", objectives = "" }
WordHunterWoW_QuestEN[14043] = { title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Mulgore sweet potatoes. They're used to make delicious candied sweet potatoes, my favorite part of the Pilgrim's Bounty meal.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. If you're headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I've been trying to keep him supplied, but everything goes so fast over there.", objectives = "" }
WordHunterWoW_QuestEN[14044] = { title = "Undersupplied in the Undercity", description = "Thanks for bringing the candied sweet potatoes. There's so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he's on the verge of running out of stuffing and cranberry chutney. I don't suppose you'd be willing to step in and whip up some more of each? The vendor should have all the ingredients you need.\n\nYou should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.", objectives = "" }
WordHunterWoW_QuestEN[14045] = { title = "Find Baron Longshore", description = "That dirty pirate Baron Longshore was the terror of these waters before the Alliance demolished his fleet and rounded up the survivors. Am I happy about it? Do I look like a bundle of joy and good cheer, {name}?\n\nLongshore raided some of my most valuable cargo before his capture. Rumor has it he buried it before he was caught. I want my goods back! Find Longshore in the Alliance camp just south of here and see if you can get him to reveal where my treasure is.", objectives = "" }
WordHunterWoW_QuestEN[14046] = { title = "The Baron's Demands", description = "I'm bound fer that gallows fer sure, mate. That treasure's no good to me now...\n\nUnless I can use it ta buy me life. I'll make a deal with ye, {race}. Smash these manacles and I'll tell ye where me treasure's buried.\n\nOh, me word is good, friend. I used ta be a real Baron, ye know.", objectives = "" }
WordHunterWoW_QuestEN[14047] = { title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a centerpiece, and for us, that's a slow-roasted wild turkey. I can't think of anything better to bring the meal together.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn't have a problem finding any.\n\nOnce you're done roasting them, will you bring them to Francis Eaton outside Orgrimmar?", objectives = "" }
WordHunterWoW_QuestEN[14048] = { title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", objectives = "" }
WordHunterWoW_QuestEN[14049] = { title = "A Most Unusual Map", description = "Here's the deal, mate: to protect me treasure map, I tattooed it onto me first mate's scalp.\n\nOf course, he's dead now, along with most of me crew. The Alliance doesn't even know what they have - his severed head is hanging from a tree at the entrance to this camp.\n\nGrab that head and take it to Gazlowe back in Ratchet.", objectives = "" }
WordHunterWoW_QuestEN[14050] = { title = "Gazlowe's Fortune", description = "Sink me, you were right! There's a map tattooed on the skull.\n\nThat cursed Baron - he buried my treasure right under my nose. Or, above my head, anyway. The map points to a place on the bluffs over Ratchet, to the south.\n\nFollow the road west out of the city, get atop the hill, head south, then run back towards the coast and look for an enormous tree overlooking the bay. Fetch my treasure and I'll split it with you!", objectives = "" }
WordHunterWoW_QuestEN[14051] = { title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", objectives = "" }
WordHunterWoW_QuestEN[14052] = { title = "Take it up with Tony", description = "This pirate situation is really crimping my operation. Cap'n Garvey is attacking any vessel in sight, even the ones whose owners paid me my bogus \"protection\" money. We need to get these pirates on the take, and fast!\n\nI know just the guy, one of Garvey's Lieutenants who's open to wheeling and dealing the Dizzywig way. He's offered to arrange a little 'mutiny' for me. Once we get these guys working for us, it's all gravy, see?\n\nTalk to my boy Tony Two-Tusk on Fray Island to the south.", objectives = "" }
WordHunterWoW_QuestEN[14053] = { title = "We're Out of Cranberry Chutney Again?", description = "My husband, Jasper, was going to make more cranberry chutney, but it looks like he's busy trying to make sure there's enough candied sweet potatoes for all the guests. Would you be willing to help? If you're a cook, you can get the tangy Wetlands cranberries you'll need from the Pilgrim's Bounty vendor outside Ironforge.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", objectives = "" }
WordHunterWoW_QuestEN[14054] = { title = "Easy As Pie", description = "Isaac's been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running out of one of Isaac's favorites, pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Elwynn pumpkins from the Pilgrim's Bounty vendor outside Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[14055] = { title = "She Says Potato", description = "My wife Ellen has enlisted my help in keeping the tables stocked, but she can't make up her mind. First I was making pumpkin pie, but now she's changed her mind and she wants candied sweet potatoes.\n\nWell, I've already started on the pie, so maybe you can help me whip up those sweet potatoes. She'll be pleasantly surprised if we can get everything she's asked for.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Darnassus. Thanks, {name}.", objectives = "" }
WordHunterWoW_QuestEN[14056] = { title = "Glomp is Sitting On It", description = "What? Leave it to Dizzywig to expect a mutiny on the cheap.\n\nNo matter, mon, we can make this work. First we need the money. Cap'n Garvey likes to hoard the loot we've been earnin', money I can use to pay off my handpicked mutineers.\n\nThe treasure pile is just outside the barracks here. You'll need to take care of Cap'n Garvey's \"treasurer\" first. Now, Glomp ain't no pushover. Believe me, I tried pushing him over once. He don't budge for nothin'.", objectives = "" }
WordHunterWoW_QuestEN[14057] = { title = "Guns. We Need Guns.", description = "Now, any good mutiny is going to need serious firepower. Cap'n Garvey claimed all the best firearms for himself: A whole shipment of big, heavy dwarven flintlocks. He keeps them at his side in the other building across the island. Grab me six of those rifles and I'll distribute them to me future officers...", objectives = "" }
WordHunterWoW_QuestEN[14058] = { title = "She Says Potato", description = "Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes.  Normally, I'd love to help, but I've promised the hostess that I'd help her watch the tables.\n\nI'd really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Thunder Bluff. Thanks, {name}.", objectives = "" }
WordHunterWoW_QuestEN[14059] = { title = "We're Out of Cranberry Chutney Again?", description = "I wish I knew why we're going through cranberry chutney so fast. Sometimes, I think they're feeding it to the abominations when I'm not looking. Would you be willing to help me make up a new batch? If you're a cook, you can get the tangy Southfury cranberries you'll need from the Pilgrim's Bounty vendor outside Orgrimmar.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", objectives = "" }
WordHunterWoW_QuestEN[14060] = { title = "Easy As Pie", description = "Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running low on pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Tirisfal pumpkins from the Pilgrim's Bounty vendor outside the Undercity.", objectives = "" }
WordHunterWoW_QuestEN[14061] = { title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", objectives = "" }
WordHunterWoW_QuestEN[14062] = { title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", objectives = "" }
WordHunterWoW_QuestEN[14063] = { title = "Mutiny, Mon!", description = "Now for my favorite part of any mutiny: the killin'! For pirates, it doesn't matter who's supposed to be in charge, only who's in control of the ships. Anchored on the east end of this island is the Maiden's Dagger, Cap'n Garvey's old flagship. He left his most trusted officer in charge: Alicia Cuthbert. Once we take her out, the ship is ours, and so's the sea.\n\nI'll get the men onto the boats. I need you to board the Dagger and blow this horn from on deck - that'll be our signal to board. Yar!", objectives = "" }
WordHunterWoW_QuestEN[14064] = { title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", objectives = "" }
WordHunterWoW_QuestEN[14065] = { title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", objectives = "" }
WordHunterWoW_QuestEN[14066] = { title = "Investigate the Wreckage", description = "Not long ago, a shipment of silver was stolen en route from here to Crossroads. It was meant as payroll to the guards, and we want that silver back.\n\nI'll ask around here for clues, but I want you to investigate the scene of the crime. Head west and look for a crashed caravan wagon just north of the road between here and Crossroads. Find out who took our silver and get it back!", objectives = "" }
WordHunterWoW_QuestEN[14067] = { title = "The Stolen Silver", description = "It's clear that these raptors acted alone to steal the Horde's silver.\n\nIt's time to teach these beasts a lesson.", objectives = "" }
WordHunterWoW_QuestEN[14068] = { title = "Waptor Twapping", description = "Waptor twapping can be wough, but I've designed new waptor twaps that ewiminate much of the wisk.\n\nSet the twap on the gwound and it will scweech wike a waptor, luwing one into the twap.\n\nWhen a waptor steps on my waptor twap, it'll shwink down so that it's wess dangewous. It's wewwy easy! I would do it myself but wecentwy I wan acwoss King Weapercwaw.", objectives = "" }
WordHunterWoW_QuestEN[14069] = { title = "Good Help is Hard to Find", description = "I've failed! I tried to meet our Kaja'Cola quotas, but you know troll slaves these days. Good help is hard to find!\n\nI think your personal touch is called for. Go show 'em what happens to slackers. If all else fails, a shock from the battery on your Goblin All-In-1-Der Belt should do the trick. Adjust their attitudes and the rest will fall in line.\n\nKaja'Cola production must continue or the Trade Prince will have all of our heads!", objectives = "" }
WordHunterWoW_QuestEN[14070] = { title = "Do it Yourself", description = "We need to send a message to several deadbeats. Of course, they're hiding out in Drudgetown, the scum. I know how you hate going into the slums, boss-man, but what can we do?\n\n<Sassy rifles through some paperwork.>\n\nI have all of the names right here.\n\nMight I suggest a little 'personal visit'? A couple of strategic beatdowns will send a message to the other debtors AND your competition.\n\n{name} is not a goblin to be trifled with!", objectives = "" }
WordHunterWoW_QuestEN[14071] = { title = "Rolling with my Homies", description = "{name}, you're about to host the corporate party to end all corporate parties. My research says that if you're seen having a good time at the party, your promotion quotient will skyrocket and explode!\n\nSo, with that in mind, might I suggest that you take your new company hot rod out for a spin?\n\nGo pick up your friends. Just remember me on the way up when it all comes together and you're the new Trade Prince, okay?", objectives = "" }
WordHunterWoW_QuestEN[14072] = { title = "Flushing Out Verog", description = "Regthar Deathgate sent me here to observe the centaur activity, but the leader of this group is hard to pin down. I've discovered that his name is \"Verog the Dervish,\" but his whereabouts are a mystery.\n\nCan you help me do some digging? I know that \"Centaur Intelligence\" sounds like an oxymoron, but their camps are often littered with important communications. Search the centaur tents all around the Stagnant Oasis here and bring me back some info.", objectives = "" }
WordHunterWoW_QuestEN[14073] = { title = "Deathgate's Reinforcements", description = "{name}! Your reputation among the Horde grows. I've been hearing reports from both the Forgotten Pools and the Stagnant Oasis that you've been a real bane to our centaur foes. Well done, indeed.\n\nRegthar Deathgate is in charge of our operations against the centaur all over the Northern Barrens. He could use a bold {class} like yourself to bolster his forces. Report to him at his outpost along the road west of here and aid him in any way he requires. ", objectives = "" }
WordHunterWoW_QuestEN[14074] = { title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", objectives = "" }
WordHunterWoW_QuestEN[14075] = { title = "Trouble in the Mines", description = "We've got trouble down in the Kaja'mine again, boss. The tunneling worms have returned and they're literally eating away at the Kajaro Trading Company's profits!\n\nKaja'mite mining is down, which is negatively impacting our production of Kaja'Cola!\n\nI tried calling the exterminator, but he's fled with the last payment we made to him.\n\nDo you think you could head into the three mines and take care of it? I'd help but I still haven't attended the cartel-mandated fighter training seminar.", objectives = "" }
WordHunterWoW_QuestEN[14076] = { title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there.  Rouse the deep jormungar, kill them, and gather their egg sacs.", objectives = "" }
WordHunterWoW_QuestEN[14077] = { title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have given me much to consider. It is not enough to fight beside the crusaders; we must take up their mission.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", objectives = "" }
WordHunterWoW_QuestEN[14078] = { title = "Lockdown!", description = "What are you still doing here, citizen?  Haven't you heard?  The city's under complete lockdown.\n\nGo see Lieutenant Walden -- he'll give you further directions for evacuation.", objectives = "" }
WordHunterWoW_QuestEN[14079] = { title = "Learn to Ride in Elwynn Forest", description = "This pamphlet advertising riding training and mount purchases was sent from Randal Hunter.\n\nRandal can be found at Elwynn Forest's Eastvale Logging Camp, along the road east out of Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[14080] = { title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", objectives = "" }
WordHunterWoW_QuestEN[14081] = { title = "Learn to Ride in the Eversong Woods", description = "This pamphlet advertising riding training and mount purchases was sent from Perascamin.\n\nPerascamin can be found at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City.", objectives = "" }
WordHunterWoW_QuestEN[14082] = { title = "Learn to Ride at the Exodar", description = "This pamphlet advertising riding training and mount purchases was sent from Aalun.\n\nAalun can be found at the entrance to the Exodar on Azuremyst Isle.", objectives = "" }
WordHunterWoW_QuestEN[14083] = { title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Ultham Ironhorn.\n\nUltham can be found at the Amberstill Ranch in Dun Morogh, found along the road east out of Ironforge.", objectives = "" }
WordHunterWoW_QuestEN[14084] = { title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Binjy Featherwhistle.\n\nBinjy can be found at Steelgrill's Depot, just northeast of Kharanos in Dun Morogh.", objectives = "" }
WordHunterWoW_QuestEN[14085] = { title = "Learn to Ride in Darnassus", description = "This pamphlet advertising riding training and mount purchases was sent from Jartsam.\n\nJartsam can be found at the Cenarion Enclave in Darnassus.", objectives = "" }
WordHunterWoW_QuestEN[14086] = { title = "Learn to Ride in Orgrimmar", description = "This pamphlet advertising riding training and mount purchases was sent from Kildar.\n\nKildar can be found in Orgrimmar's Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[14087] = { title = "Learn to Ride in Mulgore", description = "This pamphlet advertising riding training and mount purchases was sent from Kar Stormsinger.\n\nKar can be found in Mulgore's Bloodhoof Village.", objectives = "" }
WordHunterWoW_QuestEN[14088] = { title = "Learn to Ride in Durotar", description = "This pamphlet advertising riding training and mount purchases was sent from Xar'Ti.\n\nXar'Ti can be found at Sen'jin Village in southern Durotar.", objectives = "" }
WordHunterWoW_QuestEN[14089] = { title = "Learn to Ride in Tirisfal Glades", description = "This pamphlet advertising riding training and mount purchases was sent from Velma Warnam.\n\nVelma can be found at Brill in Tirisfal Glades.", objectives = "" }
WordHunterWoW_QuestEN[14090] = { title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", objectives = "" }
WordHunterWoW_QuestEN[14091] = { title = "Something's Amiss", description = "The lieutenant appears to have died from severe wounds.  The prince might want to hear this news.\n\nYou hear the sound of fighting coming from the market.", objectives = "" }
WordHunterWoW_QuestEN[14092] = { title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. The sound will rouse the deep jormungar. Kill them, collect their egg sacs, and return to the tournament grounds.", objectives = "" }
WordHunterWoW_QuestEN[14093] = { title = "All Hell Breaks Loose", description = "Worgen!  My father had warned me that Archmage Arugal's creations had run amok.\n\nBut where are they coming from?\n\nI suppose it doesn't matter.  Help us make quick work of them.  We'll show them what we Gilneans are made of!", objectives = "" }
WordHunterWoW_QuestEN[14094] = { title = "Salvage the Supplies", description = "Listen, {name}.  We can't let our supplies get destroyed.\n\nWith Gilneas walled off from the outside world, we won't last through winter if we lose much more of our stock.\n\nPlease help me salvage what you can.", objectives = "" }
WordHunterWoW_QuestEN[14095] = { title = "Identifying the Remains", description = "A whole tooth from a dead Kraken is a rare find indeed.  Crusader Silverdawn will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[14096] = { title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tournament grounds, Kul gathered the aspirants for an assault.\n\nWithout reinforcements, Kul and his followers were easily captured. I have no doubt that the cult will sacrifice the prisoners unless we can mount a rescue. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.", objectives = "" }
WordHunterWoW_QuestEN[14098] = { title = "Evacuate the Merchant Square", description = "The civilians aren't safe here anymore.  Not even inside their homes.\n\nWe're doing our best to stop the worgen from getting indoors, but their numbers are too great.\n\nHelp us by evacuating the civilian homes.  My father's army in the prison district will be able to better protect them.", objectives = "" }
WordHunterWoW_QuestEN[14099] = { title = "Royal Orders", description = "It's time for you to leave, {name}.  Go to the Military District with the other civilians.\n\nCheck in with Gwen Armstead when you cross the bridge to the southeast... see if everyone's okay.\n\nI will stay here with the guards and cover the civilians' retreat.\n\nGo now.  That is an order!", objectives = "" }
WordHunterWoW_QuestEN[14101] = { title = "Drottinn Hrothgar", description = "The Kvaldir, seafaring vrykul who raid ships and coastal settlements, have overrun a tuskarr  island across the strait to the north. Their leader is a veteran raider, Drottinn Hrothgar, who seeks to control these seas.\n\nWith him in power, our shipments and troop transports will never be safe. We will be stranded here at the Lich King's mercy.\n\nTake this captured Kvaldir war horn to the circle of tuskarr statues on the northeastern part of Hrothgar's Landing and use it to challenge the Kvaldir leader.", objectives = "" }
WordHunterWoW_QuestEN[14102] = { title = "Mistcaller Yngvar", description = "The Kvaldir have returned to the coasts of Northrend and if left unchecked, they will prevent our supplies and reinforcements from arriving. One of them, known as Mistcaller Yngvar, has taken up residence in a cave on the western side of Hrothgar's Landing. There, he manipulates the mists to conceal the Kvaldir and  the sea beasts they command.\n\nTake this charm and travel across the strait north of the tournament grounds, to Hrothgar's Landing. Find the mistcaller's cave and use the charm to reveal him.", objectives = "" }
WordHunterWoW_QuestEN[14104] = { title = "Ornolf The Scarred", description = "Ornolf the Scarred is a fearsome raider renowned among his Kvaldir brethren for raiding and capturing ships. From aboard Bor's Fury, he and his crew attack our ships and steal our goods.\n\nOrnolf and his men are among those who slaughtered the inhabitants of a tuskarr island to the north and renamed it Hrothgar's Landing. His ship sits at anchor at the eastern end of the island's harbor. Take this captured banner and display it on his ship to provoke him into facing you in battle.", objectives = "" }
WordHunterWoW_QuestEN[14105] = { title = "Deathspeaker Kharos", description = "The Cult of the Damned has redoubled its efforts to see us destroyed. They have grown bold and are massing their strength at Deathspeaker's Watch on the ridge west of the tournament grounds.\n\nThe ruthless Deathspeaker Kharos has his men fortifying their positions, preparing to unleash all of the cult's weapons.\n\nMy men are preparing themselves and the valiants to defend the grounds, but I want champions like you, {name}, to lead our efforts to blunt the attack. Find Deathspeaker Kharos and slay him.", objectives = "" }
WordHunterWoW_QuestEN[14107] = { title = "The Fate Of The Fallen", description = "The Argent Crusade is hardly the first force to challenge the Lich King. Our enemy turns spirits of the fallen against us.\n\nTheir spirits wander the Valley of Fallen Heroes, southwest of the grounds and between Aldur'thar and the Ironwall Rampart. The area is littered with discarded soul crystals, used by the Scourge to control the spirits. Gather those soul crystals and use them with this Light-blessed relic to bestow the blessing of peace upon the spirits. They have more than earned their rest.", objectives = "" }
WordHunterWoW_QuestEN[14108] = { title = "Get Kraken!", description = "The Sunreavers and Silver Covenant sent ships north to engage the Kvaldir at Hrothgar's Landing, but were intercepted and detained by a Kvaldir Raiding vessel.  To make matters worse, the Kvaldir have found a way to call forth the dreaded Kraken that lives beneath the North Sea.  If anyone on board is to get out alive, that Kraken must be driven away and the Kvaldir's summoning ritual ... disrupted.\n\nCrusader, take these spears and an Argent Hippogryph will take you to the battle.", objectives = "" }
WordHunterWoW_QuestEN[14109] = { title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", objectives = "" }
WordHunterWoW_QuestEN[14110] = { title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", objectives = "" }
WordHunterWoW_QuestEN[14112] = { title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed the beast surplus Sunreavers. The creature has a predilection for shark meat, so I want you to fly down to the Silver Blade, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", objectives = "" }
WordHunterWoW_QuestEN[14113] = { title = "Life of the Party", description = "Oh my gosh, babe! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time. You are going to look so good!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to slip into something even more amazing!", objectives = "" }
WordHunterWoW_QuestEN[14115] = { title = "Pirate Party Crashers", description = "Oh my gosh! Pirates!\n\n{name}, there are Southsea pirates crashing your party!\n\nYou have to get in there and do something about this or your career, and any chance of you being the next Trade Prince, is going to be ruined!", objectives = "" }
WordHunterWoW_QuestEN[14116] = { title = "The Uninvited Guest", description = "While you were dealing with the pirates, I noticed the Trade Prince slip upstairs. He's up on the balcony at the top of the stairs.\n\n{name}, I think he's the one that sent the pirates.\n\n<Sassy cringes.>\n\nYou'd better get up there A.S.A.P.! You wouldn't want to keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[14117] = { title = "The Eyes of Ashenvale", description = "Our enemies abound, {class}, even here at our very doorstep. The night elves have reinforced Talrendis Point in an attempt to stop our advance into Ashenvale. As we speak, their scouts patrol the nearby hills, reporting every movement to and from these gates.\n\nWe must remove these eyes of Ashenvale.\n\nGo. Your prey stalks all around these gates, especially to the east. Slay the scouts who shadow us!", objectives = "" }
WordHunterWoW_QuestEN[14118] = { title = "Venison for the Troops", description = "As we chew up the resources of this land for our war machines, we deprive the local animals of their homes. If they are to die anyway, we should not allow that meat to go to waste. Not when the maw of Orgrimmar gapes open, hungry.\n\nKill the weakened mosshoof stags that remain in this area and collect their meat for our peons and grunts. ", objectives = "" }
WordHunterWoW_QuestEN[14120] = { title = "A Bazillion Macaroons?!", description = "You're an extremely ambitious young goblin, {name}. Maybe a little too ambitious for your own good. I see a lot of myself in you when I was your age.\n\nI have a proposition. You might have noticed that Mount Kajaro is exploding thanks to your dragon. Everyone on Kezan is going to die!\n\nBut, if you bring me a bazillion macaroons before my yacht leaves the island, I'll make sure that you're one of the lucky few to escape.\n\nIf you want to live, you better hurry and figure out how to get me my moolah!", objectives = "" }
WordHunterWoW_QuestEN[14121] = { title = "Robbing Hoods", description = "We're all going to die!!!\n\n<You slap Megs to calm her down.>\n\nSorry about that, Mr. {name}. Okay, we need to find a way to get a lot of moolah quickly.\n\nThere are reports of the Trade Prince sending hired looters into the streets.\n\nYou could take the hot rod out there and run them down, snatching the loot that they've illegally stolen. There wouldn't be anything wrong with that, right?", objectives = "" }
WordHunterWoW_QuestEN[14122] = { title = "The Great Bank Heist", description = "All of your assets have been frozen and the First Bank of Kezan is out of business!\n\nYou need an awful lot of moolah, boss. I think you're going to have to go break your own money out of the bank! The different widgets in your Goblin All-In-1-Der belt should be enough to crack the vault.\n\nI just hope that you've been saving for a rainy day like I always told you to do. You might have noticed... it's raining hot liquid magma!!!", objectives = "" }
WordHunterWoW_QuestEN[14123] = { title = "Waltz Right In", description = "There's only one way we're going to get a bazillion macaroons: stealing from the rich!\n\nThat slime, the Trade Prince, has stolen all kinds of antiques and expensive art. It's time to take them back and give them to the needy... mainly us!\n\nHobart left behind a cap he was working on. It's a disguise that'll make you look like one of Gallywix's mooks. All you have to do is waltz right in to his Villa to the west and 'procure' the items.\n\nJust watch out for his pigs who can smell through the disguise!", objectives = "" }
WordHunterWoW_QuestEN[14124] = { title = "Liberate the Kaja'mite", description = "Sir, we need tons of moolah to pay the Trade Prince and get off Kezan! Well, tons of it is just waiting for the taking down there in the Kaja'mine!\n\nThese are the last known deposits of kaja'mite anywhere. This is the raw stuff that made us the genius tinkerers and alchemists we are today. If that's not worth a bazillion macaroons, I don't know what is!\n\nTake some of my kablooey bombs and blowup the deposits. Then, pick up the chunks.\n\nJust watch out for the rebellious trolls!", objectives = "" }
WordHunterWoW_QuestEN[14125] = { title = "447", description = "We're close, but we still don't have enough macaroons. But, I've got a plan: we're going to collect on the headquarters insurance policy!\n\nHope you don't mind, but I filled the place with the leftover fireworks from your party. All you have to do is go in there and sabotage things.\n\nMight I suggest the faulty generator, the leaky stove, and the flammable bed? Then, come back outside and use the control panel to send in the gasbot.\n\nIt's a foolproof plan!", objectives = "" }
WordHunterWoW_QuestEN[14126] = { title = "Life Savings", description = "We've got all of the moolah that we need. There's only one thing left to do now, boss: get you to the Trade Prince's yacht. It's about to leave port!\n\nWe're gonna have to hurry. Hop in, 'cause I'm driving!", objectives = "" }
WordHunterWoW_QuestEN[14127] = { title = "Return of the Highborne?", description = "The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink.\n\nAg'tor will no doubt want to see this important piece of intelligence. ", objectives = "" }
WordHunterWoW_QuestEN[14128] = { title = "Return of the Highborne?", description = "Our blood elven allies have been examining the ruins marked on this map, and can likely understand this mysterious script. Seek out the one called Malynea Skyreaver. She conducts her research from the Orgrimmar Rocketway Exchange just north of here - it's part of the new goblin transit system that snakes across this land. Quickly, now!", objectives = "" }
WordHunterWoW_QuestEN[14129] = { title = "Runaway Shredder!", description = "I've been trying to impress our new Horde allies with our legendary goblin efficiency, but in hindsight automating the shredders was a bad idea. Now they're mindless killing machines, rampaging over the countryside. Don't get me wrong - that kind of thing has its place - but for the time being I need a brave {class} to help me get these things under control.\n\nIt's easy. Automated shredders, like all machines, must first be beaten into submission. Afterwards, seize the controls and I'll radio you instructions.", objectives = "" }
WordHunterWoW_QuestEN[14130] = { title = "Friends Come In All Colors", description = "My brothers and I are being hunted.\n\nOur sire was recently killed and the black dragonflight seeks to rout those of us that still live. I'm here to find Azuregos and take him to safety, if only he would let it be that easy.\n\nAzuregos doesn't make many friends, and his taste in them tends to be a bit... unique. The only one I know of here is a murloc named Ergll. You should be able to find him on the coast northeast of here.\n\nDo whatever it takes to find Azuregos and send him to me.\n\nPlease hurry.", objectives = "" }
WordHunterWoW_QuestEN[14131] = { title = "A Little Pick-me-up", description = "Azuregos... Azuregos. Azy? The dragon? We're friends, definitely! Taught me to speak. Said he liked my hue... kinda colorist, eh?\n\nDon't remember where he went. Mmm... maybe something to help my memory?\n\nI plant Kawphi plants all over the beach. They like sand. Kinda weird.\n\nCould you go collect some?", objectives = "" }
WordHunterWoW_QuestEN[14132] = { title = "That's Just Rude!", description = "I'd share if they asked. They just go clickity-claking up my kawphi plants. So rude! You should teach them a lesson.\n\nDumb Makrinni.", objectives = "" }
WordHunterWoW_QuestEN[14134] = { title = "The Captain's Logs", description = "Now that you've got that thing under control, let's gather up the lumber I was supposed to be collecting. Otherwise these orcs are going to build a catapult out of ME!\n\nFresh lumber should be stockpiled all around the area. Use the shredder to collect all you can.", objectives = "" }
WordHunterWoW_QuestEN[14135] = { title = "Up a Tree", description = "Hold still a second, I'm going to bring your main buzzsaw controls online.\n\nNight elven snipers from Talrendis have been hiding in the trees, taking potshots at my workers. I want you to take care of those snipers... by first taking care of those trees. Look for Azshara saplings east of the main gates. Your shredder will know what to do. Chop to it!", objectives = "" }
WordHunterWoW_QuestEN[14136] = { title = "Rescue at Sea", description = "The Kvaldir have set up camp at Hrothgar's Landing, the small island to the North.  We sent Captain Aerthas Firehawk to the area, but they ran into a Kvaldir Raiding party heading to the Tournament Grounds!  The Firehawk is now under attack by the raiders and is vastly outnumbered. Get out there and show those Kvaldir why attacking the Sunreavers is a poor plan indeed. \n\nThe Firehawk is between Hrothgar's Landing to the north and the Tournament Grounds, on the western side of The Sea Reaver's Run.", objectives = "" }
WordHunterWoW_QuestEN[14138] = { title = "Taking Care of Business", description = "With all of the troubles down in the Kaja'mine, Foreman Dampwick's been going crazy trying to find you. He said something about some 'defiant trolls'.\n\nThe kaja'mite that our trolls are mining is critical ingredient in Kaja'Cola. That bubbly stuff is making us a fortune, and it's going to get you a promotion to Trade Prince!\n\nBut first, we have to get production flowing again. You'll find the foreman to the east. Here, give him this as an incentive to get his act together.", objectives = "" }
WordHunterWoW_QuestEN[14140] = { title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", objectives = "" }
WordHunterWoW_QuestEN[14141] = { title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", objectives = "" }
WordHunterWoW_QuestEN[14142] = { title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tourney grounds, Kul gathered the aspirants for an attack.\n\nThey were easily captured, and now Kul languishes in a cage on the platform in the camp. I am sure that the cult will sacrifice the prisoners unless we can rescue them. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.\n", objectives = "" }
WordHunterWoW_QuestEN[14143] = { title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", objectives = "" }
WordHunterWoW_QuestEN[14144] = { title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have made me think. We fight beside the crusaders, but we can learn from them, too.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", objectives = "" }
WordHunterWoW_QuestEN[14145] = { title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed some Silver Covenant members to the beast. The creature prefers shark meat, so I want you to fly down to the Crimson Dawn, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", objectives = "" }
WordHunterWoW_QuestEN[14146] = { title = "Defend the Gates!", description = "Egah - what's going on?\n\n<Screams, shouts, and the roar of combat fills the radio.>\n\n{name}! Get back here right away. Hurry back to the gates - we're under attack!\n\nHelp us fend off the invaders. I'm arming your grenade launcher!!", objectives = "" }
WordHunterWoW_QuestEN[14152] = { title = "Rescue at Sea", description = "Champion, Captain Wavecrest and her ship were sent north to disrupt the Kvaldir in Hrothgar's Landing when they were intercepted by a Kvaldir raiding party headed to the Tournament Grounds. Unfortunately, the Kvaldir far outnumber the crew on board and are slowly taking over the ship.\n\nWe need you to go north to The Wavecrest in The Sea Reaver's Run, between the Tournament Grounds and Hrothgar's Landing and help the crew fend off the attack.  You should see the ship on the east side of the pass.", objectives = "" }
WordHunterWoW_QuestEN[14153] = { title = "Life of the Party", description = "Oh wow, baby! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time already. You are going to look so fine!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to grab my stuff.", objectives = "" }
WordHunterWoW_QuestEN[14154] = { title = "By the Skin of His Teeth", description = "One of those mangy fleabags got Dempsey real good.  We cannot move him until we stabilize his bleeding.\n\nGive us a hand holding back these mongrels.  A couple of minutes is all we need, brother!", objectives = "" }
WordHunterWoW_QuestEN[14155] = { title = "Arborcide", description = "How's that shredder holding up? I think I can bring your emergency power supplies online - that'll recharge you when you're wounded.\n\nListen, these night elves are being strengthened by an ancient of war who's taken root just west of the gates. He's a big, giant tree. You know what to do! Take him out!\n\nYou were made for this!!", objectives = "" }
WordHunterWoW_QuestEN[14157] = { title = "Old Divisions", description = "Lord Darius Crowley has been called many things.  Rebel.  Traitor.  Terrorist.\n\nBefore the civil war I called him... friend.\n\nI never blamed him for leading an insurrection against me.  His land and people were separated from Gilneas by a stone wall... but we had no choice.\n\nRegardless... Crowley is exactly the type of person we need now.\n\nEnter Stoneward Prison and ask Captain Broderick about Crowley's whereabouts.  I'd send my own men, but there's still bad blood.", objectives = "" }
WordHunterWoW_QuestEN[14159] = { title = "The Rebel Lord's Arsenal", description = "The arsenal Crowley speaks of is in the cellar of a building just west of here.\n\nIt is unnerving that artillery was smuggled inside the city by my enemies, yet it might end up saving Gilnean lives today.\n\nFind Josiah Avery and requisition the rebel artillery.  We will put the weapons to good use.", objectives = "" }
WordHunterWoW_QuestEN[14160] = { title = "Writ of Merit", description = "This fine parchment lists a great many accomplishments, achieved by {name}, in the tradition of jewelcrafting.\n\nReturn this writ to Timothy Jones in Dalaran for a proper reward.", objectives = "" }
WordHunterWoW_QuestEN[14161] = { title = "Basilisk Bashin'", description = "We moved this whole mountain to strip mine the minerals below. But what we didn't take into consideration were the subterranean basilisks that are now, uh, terranean. You look like you've got some initiative - go in there and kill some of those nuisances and I'll dip into our petty cash fund for you.", objectives = "" }
WordHunterWoW_QuestEN[14162] = { title = "Report to Horzak", description = "You've done a bangup job getting our lumber operations in order. But word on the wire is that we're falling under our stone quota. You'd think if we could move mountains, we could gather up a few rocks...\n\nWell, that's not my problem, but maybe you can make it yours. Report to Horzak Zignibble up ahead at the Orgrimmar Rocketway Exchange. See if you can't help him straighten out his operations. Just follow the road northeast and find him in the rocketway tower.", objectives = "" }
WordHunterWoW_QuestEN[14165] = { title = "Stone Cold", description = "Workers act like it's their job to complain. If it isn't the backbreaking labor, the long hours, or the low pay, it's being turned to stone by basilisks. It's always something!\n\nBut I'm thinking maybe this whole workers-to-stone business could be a big moneymaker for me. What if those guys are now high-quality stone? My whiny employees could be worth more to me as luxury building materials than a source of labor! Grab a stonified mountainfoot miner and haul him or her back to me. ", objectives = "" }
WordHunterWoW_QuestEN[14166] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "" }
WordHunterWoW_QuestEN[14167] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "" }
